-- TwoPills 앱 DB: 테이블 + 기준 데이터(약·성분·조합 규칙)
-- 만든 날: 2026-10-30. 원본: src/lib/schema.ts, data/drugs/otc_core.json, data/seed/*.json
-- Supabase SQL Editor에 통째로 붙여 실행하면 된다. 여러 번 실행해도 같은 결과(기준 데이터는 지우고 다시 넣음).
-- 참고: 앱은 DATABASE_URL로 처음 뜰 때 이 내용을 스스로 만든다. 이 파일은 미리 넣어 두거나 내용을 확인하는 용도다.
--
-- 페르소나(data/seed/personas.json)에 필요한 데이터
--   1) substance(성분): 레보티록신·칼슘·오메가3·마그네슘·비타민D(페르소나 목록), 철분·비타민C(시나리오), 추천 후보 비타민들
--   2) drug + drug_ingredient(일반의약품과 그 성분): 비맥스제트정(202300436), 타이레놀, 훼로바-유서방정 등
--   3) interaction_rule(조합 규칙·원문·출처): 레보티록신×칼슘, 비맥스제트정×칼슘, 레보티록신×철분, 칼슘×철분 …
--   4) substance.upper_limit(하루 기준량): 칼슘 과다 섭취(S8)
--   5) app_user·user_item(계정·복용 목록): 앱이 만든다. 페르소나 버튼은 누를 때마다 임시 시연 계정을 새로 만들고 하루 뒤 지운다.
--   페르소나 정의(이름·설명·처음 목록)는 DB가 아니라 data/seed/personas.json 파일에서 읽는다.
--
-- 보안: 맨 아래 ENABLE ROW LEVEL SECURITY로 anon 키(웹 API)에서는 어떤 행도 읽히지 않는다. 지우지 말 것.

BEGIN;

CREATE TABLE IF NOT EXISTS drug (
  item_seq      TEXT PRIMARY KEY,
  item_name     TEXT NOT NULL,
  company       TEXT,
  category      TEXT,
  efficacy      TEXT,
  usage         TEXT,
  warning       TEXT,
  precautions   TEXT,
  interactions  TEXT,
  side_effects  TEXT,
  storage       TEXT,
  source        TEXT,
  source_url    TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS drug_ingredient (
  item_seq    TEXT NOT NULL REFERENCES drug(item_seq) ON DELETE CASCADE,
  ingredient  TEXT NOT NULL,
  nutrient    TEXT,
  PRIMARY KEY (item_seq, ingredient)
);
CREATE INDEX IF NOT EXISTS idx_drug_ingredient_nutrient ON drug_ingredient (nutrient);

CREATE TABLE IF NOT EXISTS substance (
  id                     TEXT PRIMARY KEY,
  name                   TEXT NOT NULL,
  aliases                JSONB NOT NULL DEFAULT '[]'::jsonb,
  kind                   TEXT NOT NULL,
  is_vitamin             BOOLEAN NOT NULL DEFAULT false,
  recommendable          BOOLEAN NOT NULL DEFAULT false,
  function_claim         TEXT,
  function_source_title  TEXT,
  function_source_url    TEXT,
  nutrient_keys          JSONB NOT NULL DEFAULT '[]'::jsonb,
  summary                TEXT
);
ALTER TABLE substance ADD COLUMN IF NOT EXISTS display_name TEXT;
ALTER TABLE substance ADD COLUMN IF NOT EXISTS upper_limit JSONB;

CREATE TABLE IF NOT EXISTS interaction_rule (
  id                   TEXT PRIMARY KEY,
  a_type               TEXT NOT NULL,
  a_ref                TEXT NOT NULL,
  b_type               TEXT NOT NULL,
  b_ref                TEXT NOT NULL,
  relation             TEXT NOT NULL,
  effect               TEXT,
  quote                TEXT NOT NULL,
  quote_ko             TEXT,
  action               TEXT NOT NULL,
  pharmacist_question  TEXT NOT NULL,
  source_id            TEXT NOT NULL,
  source_title         TEXT NOT NULL,
  source_url           TEXT NOT NULL,
  source_kind          TEXT NOT NULL
);
ALTER TABLE interaction_rule ADD COLUMN IF NOT EXISTS source_note TEXT;
ALTER TABLE interaction_rule ADD COLUMN IF NOT EXISTS more_sources JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE interaction_rule ADD COLUMN IF NOT EXISTS checked_on TEXT;
CREATE INDEX IF NOT EXISTS idx_rule_a ON interaction_rule (a_type, a_ref);
CREATE INDEX IF NOT EXISTS idx_rule_b ON interaction_rule (b_type, b_ref);

CREATE TABLE IF NOT EXISTS app_user (
  id                SERIAL PRIMARY KEY,
  email             TEXT NOT NULL UNIQUE,
  password_hash     TEXT NOT NULL,
  display_name      TEXT,
  role              TEXT NOT NULL DEFAULT '복용자',
  first_checked_at  TIMESTAMPTZ,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS user_item (
  id         SERIAL PRIMARY KEY,
  user_id    INTEGER NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
  item_type  TEXT NOT NULL,
  item_ref   TEXT NOT NULL,
  added_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (user_id, item_type, item_ref)
);
-- 하루에 먹는 개수(필수)와 한 알 함량(선택, 영양제 과다 섭취 확인용)
ALTER TABLE user_item ADD COLUMN IF NOT EXISTS daily_count INTEGER NOT NULL DEFAULT 1;
ALTER TABLE user_item ADD COLUMN IF NOT EXISTS unit_amount NUMERIC;
ALTER TABLE user_item ADD COLUMN IF NOT EXISTS unit TEXT;

CREATE TABLE IF NOT EXISTS recommendation (
  id          SERIAL PRIMARY KEY,
  user_id     INTEGER NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
  survey      JSONB NOT NULL,
  result      JSONB NOT NULL,
  model       TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS seed_meta (
  key    TEXT PRIMARY KEY,
  value  TEXT NOT NULL
);

-- Supabase처럼 테이블을 웹 API(anon 키)로 바로 열어 주는 곳에서 회원 정보·목록이 새지 않게 행 단위 접근을 막는다.
-- 정책을 두지 않으므로 anon·authenticated는 아무 행도 못 읽는다. 앱은 테이블 주인 계정으로 붙어 영향이 없다.
ALTER TABLE drug ENABLE ROW LEVEL SECURITY;
ALTER TABLE drug_ingredient ENABLE ROW LEVEL SECURITY;
ALTER TABLE substance ENABLE ROW LEVEL SECURITY;
ALTER TABLE interaction_rule ENABLE ROW LEVEL SECURITY;
ALTER TABLE app_user ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_item ENABLE ROW LEVEL SECURITY;
ALTER TABLE recommendation ENABLE ROW LEVEL SECURITY;
ALTER TABLE seed_meta ENABLE ROW LEVEL SECURITY;

-- ───────── 기준 데이터 ─────────
DELETE FROM interaction_rule;
DELETE FROM drug_ingredient;
DELETE FROM drug;
DELETE FROM substance;

-- 일반의약품 59개
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('202106092', '타이레놀정500밀리그람(아세트아미노펜)', '켄뷰코리아판매유한회사', '해열진통소염', '이 약은 감기로 인한 발열 및 동통(통증), 두통, 신경통, 근육통, 월경통, 염좌통(삔 통증), 치통, 관절통, 류마티양 동통(통증)에 사용합니다', '만 12세 이상 소아 및 성인은 1회 1~2정씩, 1일 3~4회(4~6시간 마다) 필요시 복용합니다.
이 약은 가능한 최단기간동안 최소 유효용량으로 복용하며, 1일 최대 8정(4 g)을 초과하여 복용하지 않습니다.', '매일 세 잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 간손상을 일으킬 수 있습니다.
매우 드물게 치명적일 수 있는 급성 전신성 발진성 고름물집증, 스티븐스-존슨 증후군, 독성 표피 괴사용해와 같은 중대한 피부반응이 보고되었고 이 약 복용후 피부발진 또는 다른 과민반응의 징후가 나타나는 경우 즉시 복용을 중단하십시오.
아세트아미노펜으로 일일 최대 용량(4,000 mg)을 초과하여 복용하지 마십시오. 간손상을 일으킬 수 있습니다. 아세트아미노펜을 포함하는 다른 제품과 함께 복용하지 마십시오.', '이 약에 과민증, 소화성궤양, 심한 혈액 이상, 간장애, 신장(콩팥)장애, 심장기능저하 환자, 아스피린 천식(비스테로이드성 소염(항염)제에 의한 천식발작 유발) 환자 또는 경험자, 바르비탈계 약물 또는 삼환계 항우울제 복용한 환자, 알코올을 복용한 사람, 12세 미만의 소아는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 과민증 경험자, 간장애, 신장(콩팥)장애, 소화성궤양, 혈액이상 환자 또는 경험자, 출혈경향, 심장기능이상이 있는 환자, 기관지천식 환자, 고령자(노인), 임부 또는 수유부, 글루타치온 보유량이 낮은 상태의 환자는 의사 또는 약사와 상의하십시오.
복용 중에 음주하지 마십시오.', '바르비탈계 약물, 삼환계 항우울제 및 알코올을 투여한 환자, 와파린, 플루클록사실린을 복용하는 환자는 의사 또는 약사와 상의하십시오.', '쇽 증상(호흡곤란, 온몸이 붉어짐, 혈관부기, 두드러기 등), 천식발작, 혈소판감소, 과립구감소, 용혈성빈혈, 메트헤모글로빈혈증, 혈소판기능 저하(출혈시간 연장), 청색증, 과민증상(얼굴부기, 땀이 남, 저혈압), 구역, 구토, 식욕부진, 위장출혈, 소화성궤양, 천공(뚦림), 발진, 알레르기 반응, 피부점막안증후군(스티븐스-존슨증후군), 독성표피괴사증(리엘증후군), AST 상승, ALT 상승, 고정발진 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=202106092');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('202106092', '아세트아미노펜', NULL) ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('202200407', '타이레놀8시간이알서방정(아세트아미노펜)', '켄뷰코리아판매유한회사', '해열진통소염', '이 약은 해열 및 감기에 의한 동통(통증)과 두통, 치통, 근육통, 허리통증, 생리통, 관절통의 완화에 사용합니다.', '12세 이상의 소아와 성인은 1회 2정을 매 8시간마다 복용합니다. 24시간 동안 6정을 초과하지 마십시오.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 간손상을 일으킬 수 있습니다.
매우 드물게 치명적일 수 있는 급성전신성발진고름물집증, 스티븐스-존슨증후군, 독성표피괴사용해와 같은 중대한 피부반응이 보고되었고 이 약 복용 후 피부발진 또는 다른 과민반응의 징후가 나타나는 경우 즉시 복용을 중단하십시오.
아세트아미노펜으로 일일 최대 용량(4,000 mg)을 초과하여 복용하지 마십시오. 간손상을 일으킬 수 있습니다. 아세트아미노펜을 포함하는 다른 제품과 함께 복용하지 마십시오.', '이 약에 과민증, 소화성궤양, 심한 혈액 이상 환자, 심한 간장애, 심한 신장(콩팥)장애, 심한 심장기능저하, 아스피린 천식(비스테로이드성 소염(항염)제에 의한 천식발작 유발) 또는 경험자, 바르비탈계 약물 또는 삼환계 항우울제 복용한 환자, 알코올을 복용한 사람, 12세 미만의 소아는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 간장애 또는 경험자, 신장(콩팥)장애 또는 경험자, 소화성궤양의 경험자, 혈액이상 또는 경험자, 출혈경향이 있는 환자, 심장기능이상이 있는 환자, 과민증의 경험자, 기관지천식 환자, 고령자(노인), 임부 또는 수유부, 글루타치온 보유량이 낮은 상태의 환자는 의사 또는 약사와 상의하십시오.
소아 및 고령자(노인)는 최소 필요량을 복용하고 이상반응에 유의해야 합니다. 과도한 체온강하, 허탈, 사지냉각 등이 나타날 수 있습니다.
의사 또는 약사의 지시없이 통증에 10일 이상(성인) 복용하지 않고 발열에 3일 이상 복용하지 마십시오. 통증이나 발열 증상이 지속되거나 악화될 경우, 또는 새로운 증상이 나타날 경우 의사 또는 약사와 상의합니다. 고혈압 환자의 경우 의사 또는 약사의 지시가 없는 한 상기 명시된 기간보다 더 길게 이 약을 복용하지 않는다.
과량복용시 어떠한 명백한 증상이나 징후가 없더라도 신속하게 의학적 처치를 받아야 합니다. 10~12시간 이내에 N-아세틸시스테인 정맥주사를 투여받거나 메치오닌을 경구복용하여 간을 보호해야합니다.
이 약은 서방형 제제이므로 정제를 으깨거나 씹거나 녹이지 말고 그대로 삼켜서 복용해야 합니다.', '바르비탈계 약물 또는 삼환계 항우울제 복용한 환자는 이 약을 복용하지 마십시오.
다른 소염(항염)진통제와 함께 복용하지 마십시오.
와파린, 플루클록사실린을 복용하는 환자는 이 약을 복용하기 전에 의사 또는 약사와 상의하십시오.', '쇽 증상(호흡곤란, 온몸이 붉어짐, 혈관부기, 두드러기 등), 천식발작, 혈소판감소, 과립구감소, 용혈성빈혈, 메트헤모글로빈혈증, 혈소판기능 저하(출혈시간 연장), 청색증, 과민증상(얼굴부기, 땀이 남, 저혈압), 구역, 구토, 식욕부진, 위장출혈, 소화성궤양, 천공(뚦림), 발진, 피부점막안증후군(스티븐스-존슨증후군), 독성표피괴사증(리엘증후군), 고음이온차 대사성 산증(HAGMA), AST 상승, ALT 상승, 고정발진 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오. 어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=202200407');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('202200407', '아세트아미노펜', NULL) ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('202200525', '어린이타이레놀현탁액(아세트아미노펜)', '켄뷰코리아판매유한회사', '해열진통소염', '이 약은 감기로 인한 발열 및 동통(통증), 두통, 신경통, 근육통, 월경통, 염좌통(삔 통증), 치통, 관절통, 류마티양 동통(통증)에 사용합니다.', '만 12세 이하의 소아는 1회 권장용량을 4-6시간마다 필요 시 복용합니다. 1일 5회(75 mg/kg)를 초과하여 복용하지 마십시오. 연령대별 권장용량은 허가사항을 참고하십시오.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 간손상을 일으킬 수 있습니다.
매우 드물게 치명적일 수 있는 급성전신성발진고름물집증, 스티븐스-존슨증후군, 독성표피괴사용해와 같은 중대한 피부반응이 보고되었고 이 약 복용 후 피부발진 또는 다른 과민반응의 징후가 나타나는 경우 즉시 복용을 중단하십시오.
아세트아미노펜으로 일일 최대 용량(4,000 mg)을 초과하여 복용하지 마십시오. 간손상을 일으킬 수 있습니다. 아세트아미노펜을 포함하는 다른 제품과 함께 복용하지 마십시오.', '이 약에 과민증, 소화성궤양, 심한 혈액 이상 환자, 심한 간장애, 심한 신장(콩팥)장애, 심한 심장기능저하, 아스피린 천식(비스테로이드성 소염(항염)제에 의한 천식발작 유발) 또는 경험자, 바르비탈계 약물 또는 삼환계 항우울제 복용한 환자, 알코올을 복용한 사람은 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 간장애 환자 또는 경험자, 신장(콩팥)장애 환자 또는 경험자, 소화성궤양 경험자, 혈액이상 환자 또는 경험자, 출혈경향이 있는 환자, 심장기능이상이 있는 환자, 과민증의 경험자, 기관지천식 환자, 고령자(노인), 만 2세 미만의 소아, 임부 또는 수유부는 의사 또는 약사와 상의하십시오.', '복용 중 음주하지 마십시오.
아세트아미노펜을 포함한 해열진통제와 함께 복용하지 마십시오.
와파린, 플루클록사실린을 복용하는 환자는 의사 또는 약사와 상의하십시오.', '쇽 증상(호흡곤란, 온몸이 붉어짐, 혈관부기, 두드러기 등), 천식발작, 혈소판감소, 과립구감소, 용혈성빈혈, 메트헤모글로빈혈증, 혈소판기능 저하(출혈시간 연장), 청색증, 과민증상(얼굴부기, 땀이 남, 저혈압), 구역, 구토, 식욕부진, 위장출혈, 소화성궤양, 천공(뚦림), 발진, 피부점막안증후군(스티븐스-존슨증후군), 독성표피괴사증(리엘증후군), AST 상승, ALT 상승, 고정발진 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오. 어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=202200525');
