INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('200810700', '펜잘큐정', '(주)종근당', '해열진통소염', '이 약은 두통, 치통, 발치(이를 뽑음)후 동통(통증), 인후통, 귀의 통증, 관절통, 신경통, 허리통, 근육통, 어깨결림, 타박통, 골절통, 염좌통(삔 통증), 월경통(생리통), 외상(상처)통의 진통, 오한, 발열 시의 해열에 사용합니다.', '만 15세 이상 및 성인은 1회 1정씩, 만 11세 이상~만 15세 미만은 1회
