INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('200400463', '이지엔6애니연질캡슐(이부프로펜)', '(주)대웅제약', '해열진통소염', '이 약은 감기로 인한 발열 및 동통(통증), 요통, 생리통, 류마티양 관절염, 연소성(어리거나 젊은나이에 나타나는) 류마티양 관절염, 골관절염(퇴행성 관절질환), 수술후 동통(통증)과 두통, 편두통, 치통, 근육통, 신경통, 강직성 척추염, 급성통풍, 건선(건선, 마른비닐증)성 관절염, 연조직손상(염좌(삠), 좌상(타박상/멍)), 비관절 류마티스질환(건염(힘줄염), 건초염(힘줄윤활막염), 활액(윤활)낭염)에 사용합니다.', '성인은 류마티양 관절염, 골관절염, 강직성 척추염, 연조직손상, 비관절 류마티스질환, 급성통풍, 건선성 관절염에는 1회 1~3캡슐(200~600 mg)씩, 1일 3~4회, 1일 최고 16캡슐(3,200 mg)까지 복용할 수 있으며, 연소성(어리거나 젊은나이에 나타나는) 류마티양 관절염에는 1일 체중 kg당 30~40 mg을 3~4회 분할 복용, 경증 및 중등도의 동통이나 감기에는 성인 1회 1~2캡슐(200~400 mg)씩, 1일 3~4회, 편두통에는 성인 1회 1~2 캡슐(200~400 mg)씩 복용하며 24시간 동안 2캡슐을 초과하지 않습니다.
만 12세 이상 청소년은 1회 1~2캡슐(200~400 mg)씩, 1일 3~4회 복용합니다.
체중이 30 kg 미만인 경우 1일량이 500 mg을 초과해서는 안되며 공복시 복용은 피하는 것이 바람직합니다.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.
이 약 복용 시 치명적일 수 있는 중대한 심혈관계 혈전 반응, 심근경색증, 뇌졸중의 위험이 증가하며, 위장관 출혈, 궤양 및 천공 등 심각한 위장관계 이상반응이 나타날 수 있습니다.
조절되지 않는 고혈압, 울혈심부전증, 확립된 허혈성 심장질환, 말초동맥질환, 뇌혈관질환을 가진 환자는 고용량 이부프로펜(1일 2,400 mg) 복용을 피해야 하며, 심혈관계 위험 요소(고혈압, 고지혈증, 당뇨병, 흡연 등)를 가지고 있는 환자는 고용량 이부프로펜(1일 2,400 mg) 복용이 필요한 경우 이 약을 복용하기 전에 의사 또는 약사와 상의하십시오.', '이 약에 과민증 환자, 위장관 궤양, 위장관 출혈 또는 경험자, 심한 혈액이상, 심한 간장애, 심한 신장장애, 심한 심장기능부전, 심한 고혈압, 기관지천식 또는 경험자, 아스피린 또는 다른 소염진통제에 의한 천식, 두드러기, 알레르기 반응 경험자, 심장동맥 우회로술 전후 통증발생 환자, 임신 말기 3개월 기간의 임부, 수유부, 항암요법으로 고용량 메토트렉세이트를 투여 중인 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 혈액이상 또는 경험자, 출혈경향이 있는 환자, 간경화, 간장애 또는 경험자, 신장장애 또는 경험자, 심장기능부전, 심질환, 고혈압 환자, 과민증 경험자, 전신성 홍반성 루푸스, 혼합결합조직질환 환자, 궤양성 대장염, 크론병 환자, 고령자 및 소아, 임부, 수유부, 심근경색이나 뇌졸중 예방목적으로 저용량 아스피린을 복용하는 사람, 황색5호에 과민증 또는 알레르기 반응 경험자는 의사 또는 약사와 상의하십시오.
권장용량을 초과하여 복용하지 마십시오.
감기에 복용할 경우에는 원칙적으로 5일 이내로 복용하며 의사 또는 약사의 지시 없이 통증에 10일 이상(성인) 또는 5일 이상(소아) 복용하지 않고 발열에 3일 이상 복용하지 마십시오.', '다른 비스테로이드성 소염진통제와 함께 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 저용량 아스피린, ACE 저해제, 리튬, 푸로세미드 및 티아지드계 이뇨제, 저용량 메토트렉세이트, 쿠마린계 항응혈제(와파린 등), 선택적 세로토닌 재흡수억제제와 함께 복용 시 의사 또는 약사와 상의하십시오.', '쇽 증상(호흡곤란, 혈압저하 등), 헤마토크리트감소, 헤모글로빈감소, 빈혈, 재생불량성빈혈, 용혈성(적혈구파괴성)빈혈, 무과립구증, 과립구감소, 백혈구감소, 혈소판감소, 혈소판기능저하, 호산구증가 등의 혈액장애, 소화성궤양, 위장관궤양, 위장출혈, 천공(뚫림), 궤양성대장염, 혈변, 위염, 췌장염, 혈액구토, 크론병, 식욕부진, 구역, 구토, 복통, 소화불량, 설사, 위부(상복부)불쾌감, 상복부통증, 구갈(목마름), 구내염, 복부팽만감, 구강궤양, 변비, 흑변, 피부점막안증후군(스티븐스-존슨증후군), 독성표피괴사용해(리엘증후군), 빈도불명의 호산구증가 및 전신 증후군을 동반한 약물 반응(DRESS 증후군), 혈관신경성 부종, 수포성(물집성)피부염, 다형 홍반(여러 모양의 붉은 반점), 반구진 발진, 피부 붉어짐, 수포(물집), 발진, 탈락 피부염, 급성전신발진고름물집증, 간염, 황달, GOT·GPT·ALP의 상승 등과 같은 간기능이상, 간장애, 과민증 또는 아나필락시스 반응, 천식발작, 두드러기, 습진, 자주색반점, 발진, 가려움증, 천식, 기관지수축, 호흡곤란 또는 쌕쌕거림, 암점 등 시각장애, 난청, 이명, 미각이상, 현기증, 졸음, 졸음, 어지러움, 우울, 두통, 뇌혈관사고 또는 신경질, 무균성수막염 또는 수막염(심한 두통, 구역, 구토, 불면, 목이 뻣뻣함, 발열 또는 의식장애 등), 혈압저하, 혈압상승, 심계항진, 심부전, 심근경색증 또는 협심증, 급성신부전, 소변감소, 혈뇨, 요단백, BUN, 혈중크레아티닌의 상승, 고칼륨혈증, 간질성 콩팥염, 콩팥염증후군, 콩팥유두괴사, 요량감소, 전신부종(온몸 부기) 및 이에 수반하는 숨가쁨, 나른함, 안와주위부종, 안면부종, 권태감, 발열, 비출혈, 부종, 말초부종 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200400463');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('200400463', '이부프로펜', NULL) ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('200400485', '이지엔6프로연질캡슐(덱시부프로펜)(수출명:DAUFENSoftCapsule,SPEEDFEN)', '(주)대웅제약', '해열진통소염', '이 약은 만성 다발성 관절염, 류마티스관절염, 관절증, 강직척추염, 외상 및 수술 후 통증성 부종 또는 염증, 염증, 통증 및 발열을 수반하는 감염증의 치료보조에 사용합니다.', '성인은 1회 1캡슐(300 mg)씩, 1일 2~4회 복용합니다. 단, 1일 4캡슐(1,200 mg)을 초과하지 않습니다.', '매일 세 잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.
이 약 복용시 치명적일 수 있는 중대한 심혈관계 혈전 반응, 심근경색증, 뇌졸중의 위험이 증가하며, 위장관 출혈, 궤양 및 천공 등 심각한 위장관계 이상반응이 나타날 수 있습니다.', '이 약에 과민증 환자, 위장관(창자)궤양이 있거나 징후가 있는 환자 또는 경험자, 위장관(창자)이나 뇌혈관 또는 다른 부위의 출혈이 있는 환자, 심한 혈액이상, 심한 간장애, 심한 신장장애, 심한 심장기능부전, 심한 고혈압, 기관지천식 또는 경험자, 아스피린이나 다른 비스테로이드성 소염진통제에 천식, 두드러기 또는 알레르기 반응 경험자, 관상동맥 우회로술 전후에 발생하는 통증의 치료, 임신 6개월 이상의 임부, 수유부, 크론병 또는 궤양성대장염과 같은 염증성장질환 환자, 이전의 비스테로이드성 소염(항염)진통제 치료로 인해, 위장관(창자) 출혈 또는 천공(뚫림) 발생 경험이 있는 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 혈액이상 또는 경험자, 출혈경향이 있는 환자, 간장애 또는 경험자, 신장애 또는 경험자, 체액저류(체액고임) 또는 심부전 환자, 고혈압, 과민반응 경험자, 전신성 홍반성 루푸스(SLE) 및 혼합 결합조직질환(MCTD), 고령자, 6세 이상의 어린이, 위암 환자, 알코올중독 환자, 임부 또는 임신하고 있을 가능성이 있는 여성, 허혈심장병, 말초동맥질환, 뇌혈관 질환, 심혈관 질환의 위험인자가 있는 환자(예, 고혈압, 고지혈증, 당뇨병, 흡연), 간성 포르피린증, 혈액부족을 초래한 중대한 외과수술을 받은 환자, 이뇨제 또는 ACE 억제제를 투여 중인 환자, 혈액응고장애가 있거나 항응고제를 투여받고 있는 환자, 과거 비스테로이드성 소염(항염)진통제의 장기투여로 인한 소화관 궤양이 있는 환자는 의사 또는 약사와 상의하십시오.
이 약 복용 후 어지러움 또는 피로가 나타날 수 있으므로 운전 및 기계조작 시 주의하십시오.', '이 약을 복용하는 동안 다른 비스테로이드성 소염진통제, 아스피린, 고용량의 메토트렉세이트를 사용하지 마십시오.
이 약을 복용하기 전에 코르티코스테로이드, 알코올, 디곡신, 페니토인, 프로베네시드, 설핀피라존, 설포닐우레아제, ACE 억제제 또는 안지오텐신Ⅱ 수용체 길항제, 이뇨제, 리튬, 쿠마린계 항응고제(와르파린 등), 바클로펜, 면역억제제(시클로스포린, 타크로리무스, 시롤리무스), 혈전용해제, 티클로피딘, 항혈전제, 혈중 칼륨농도를 증가시키는 약물(예, 칼륨 저류형 이뇨제, ACE 억제제, 안지오텐신-Ⅱ 수용체 길항제, 시클로스포린과 타크로리무스와 같은 면역억제제, 트리메토프림, 헤파린 등), CYP2C8, CYP2C9의 유도제(예, 리팜피신, 페노바르비탈), 저용량(15 mg/주 미만)의 메토트렉세이트, 항혈소판제 및 선택적 세로토닌 재흡수 억제제를 함께 사용 시 의사 또는 약사와 상의하십시오.', '드물게 쇽(호흡곤란, 혈압저하 등), 재생불량성빈혈, 용혈성빈혈, 무과립구증, 과립구감소, 백혈구감소, 혈소판감소, 혈소판 기능 저하 (출혈시간 연장), 호산구증가 등의 혈액장애, 소화불량, 복부팽만, 속쓰림, 상복부의 통증, 설사나 변비, 때때로 식욕부진, 구역, 구토, 복통, 위부불쾌감이나 드물게 식도염, 식도협착, 게실악화, 비특이성출혈성대장염, 궤양성대장염 또는 크론병, 소화성궤양 위장출혈, 천공, 혈변, 위염, 췌장염, 매우 드물게 구갈, 구내염, 다형홍반, 전신홍반루프스, 탈모, 때때로 혈관부종, 드물게 피부점막안증후군(스티븐스-존슨증후군) 및 독성표피괴사용해(리엘증후군), 발진, 두드러기, 가려움, 자색반, 드물게 천식발작, 습진, 아나필락시스 반응, 광민감반응, 황달, ALT 상승, AST 상승, ALP 상승, 간기능이상, 간염, 때때로 비염, 기관지경련, 드물게 심부전 환자의 경우에 급성폐렴의 위험, 앞이 보이지 않음, 암침 등의 시각장애, 난청, 이명, 미각이상, 피로, 졸음, 두통, 어지러움, 때때로 불안, 안절부절, 착란, 우울증, 드물게 무균성수막염, 혈압저하, 혈압상승, 심계항진, 급성신부전, 핍뇨(소변감소), 혈뇨 등의 증상 및 요단백(소변에 포함된 단백질), BUN, 혈중 크레아티닌의 상승, 고칼륨혈증, 급성 폐부종, 말초부종, 체액저류, 고혈압, 심부전, 코니스 증후군(빈도불명), 여성의 생식능력 감소, 안와주위부종, 매우 드물게 권태감, 발열, 코피, 염증악화 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200400485');
