INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('200109769', '애드빌정(이부프로펜)', '헤일리온코리아주식회사', '해열진통소염', '이 약은 감기로 인한 발열 및 동통, 요통, 생리통, 류마티양 관절염, 연소성 류마티양 관절염, 골관절염(퇴행성 관절질환), 수술후 동통과 두통, 치통, 근육통, 신경통, 강직성 척추염, 급성통풍, 건선성 관절염, 연조직손상(염좌, 좌상), 비관절 류마티스질환(건염, 건초염, 활액낭염)에 사용합니다.', '성인은 류마티양 관절염, 골관절염, 강직성 척추염, 연조직손상, 비관절 류마티스질환, 급성통풍, 건선성 관절염에는 1회 1~3정(200~600 mg) 1일 3~4회 1일 최고 16정(3,200 mg)까지 투여할 수 있으며, 연소성 류마티양 관절염에는 1일 체중 kg당 30~40 mg을 3~4회 분할 경구 투여, 경증 및 중등도의 동통이나 감기에는 성인 1회 1~2정(200~400 mg) 1일 3~4회 복용합니다.
11~14세는 1회 200~250 mg, 7~10세는 1회 150~200 mg, 3~ 6세는 1회 100~150 mg, 1~ 2세는 1회 50~100 mg을 1일 3~4회 복용합니다.
체중이 30kg미만인 어린이는 1일량이 500 mg을 초과해서는 안되며 공복시 투여는 피하는 것이 바람직합니다.', '', '이 약에 과민증 환자, 위장관 궤양, 위장관 출혈환자 또는 경험자, 심한 혈액이상, 심한 간장애, 심한 신장장애, 심한 심장기능부전, 심한 고혈압, 기관지천식 또는 경험자, 아스피린이나 다른 비스테로이드성 소염진통제(COX-2 저해제 포함)에 대하여 천식, 두드러기, 알레르기 반응과 같은 과민증 또는 경험자, 관상동맥(심장동맥) 우회로술 전후 통증 환자, 임신 말기 3개월 기간에 해당하는 임부 또는 수유부, 항암요법으로 고용량 메토트렉세이트를 투여중인 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 혈액이상 또는 경험자, 출혈경향이 있는 환자, 간경화, 간장애 또는 경험자, 신장장애 또는 경험자, 심장기능부전 또는 심질환, 고혈압, 전신성홍반성루푸스 및 혼합결합조직질환 환자, 궤양성대장염, 크론병, 고령자 및 소아, 임부는 의사 또는 약사와 상의하십시오.', '다른 비스테로이드성 소염진통제(NSAIDs), 고용량 메토트렉세이트와 함께 복용하지 마십시오.
저용량 아스피린, 저용량의 메토트렉세이트, ACE 저해제, 리튬, 푸로세미드 및 티아지드계 이뇨제, 쿠마린계 항응혈제(와파린 등), 선택적 세로토닌 재흡수억제제와 함께 사용 시 의사 또는 약사와 상의하십시오.', '쇽 증상(가슴쓰림, 오한, 호흡곤란, 혈압저하 등), 헤마토크릿·헤모글로빈 감소, 빈혈, 재생불량성빈혈, 용혈성빈혈, 무과립구증, 과립구·백혈구·혈소판 감소, 혈소판기능저하 (출혈시간 연장), 호산구 증가, 소화성궤양, 위장관궤양, 위장출혈, 천공(뚫림), 궤양성대장염, 혈변, 위염, 췌장염, 토혈(혈액구토), 크론병, 식욕부진, 구역, 구토, 복통, 소화불량, 설사, 위부불쾌감, 상복부통증, 구갈, 구내염, 복부팽만감, 구강궤양, 변비, 흑변, 피부점막안증후군(스티븐스-존슨증후군), 독성표피괴사증(리엘증후군), 급성전신발진고름물집증, 광민감 반응(빈도불명), 빈도불명의 호산구 증가 및 전신 증후군을 동반한 약물 발진(DRESS 증후군), 혈관신경성 부종, 수포성피부염, 다형성 홍반, 반구진 발진, 피부 붉어짐, 수포(물집), 발진, 탈락 피부염, 간염, 황달, GOT, GPT, 알칼라인 포스파타제(ALP)의 상승 등과 같은 간기능이상, 간장애, 과민증 또는 아나필락시스 반응, 천식발작, 두드러기, 습진, 자반(자주색반점), 발진, 가려움증, 천식, 기관지수축, 호흡곤란 또는 쌕쌕거림, 시야불능부위 등 시각장애, 귀먹음, 귀울림, 미각이상, 현기증, 졸음, 어지러움, 우울, 두통, 뇌혈관사고 또는 신경질, 무균성수막염 또는 수막염(심한 두통, 구역, 구토, 불면, 목이 뻣뻣함, 발열 또는 의식장애 등의 증상), 혈압저하, 혈압상승, 두근거림, 심부전, 심근경색증 또는 협심증, 급성신부전, 소변감소, 혈뇨, 요단백, BUN, 혈중크레아티닌의 상승, 고칼륨혈증, 간질성 콩팥염, 콩팥염증후군, 콩팥유두괴사, 요량감소, 전신부종 및 이에 수반하는 숨가쁨, 나른함, 눈주변 부기, 얼굴부기, 권태감, 발열, 코피, 부기, 말초부종, 빈도불명의 코니스 증후군 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200109769');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('200109769', '이부프로펜', NULL) ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('197700120', '부루펜정200밀리그램(이부프로펜)', '삼일제약(주)', '해열진통소염', '이 약은 류마티양 관절염, 연소성 류마티양 관절염, 골관절염(퇴행성 관절질환), 감기로 인한 발열 및 동통, 요통, 월경곤란증, 수술후 동통과 강직성 척추염, 두통, 치통, 근육통, 신경통, 급성통풍, 건선성 관절염, 연조직손상(염좌, 좌상), 비관절 류마티스질환(건염, 건초염, 활액낭염)에 사용합니다.', '성인은 류마티양 관절염, 골관절염, 강직성 척추염, 연조직손상, 비관절 류마티스질환, 급성통풍, 건선성 관절염에는 1회 1~3정(200~600 mg) 1일 3~4회 1일 최고 16정(3,200 mg)까지 복용할 수 있으며, 연소성 류마티양 관절염에는 1일 체중 kg당 30~40 mg을 3~4회 분할 복용, 경증 및 중등도의 동통이나 감기에는 성인 1회 1~2정(200~400 mg) 1일 3~4회 복용합니다.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.
이 약 복용 시 치명적일 수 있는 중대한 심혈관계 혈전 반응, 심근경색증, 뇌졸중의 위험이 증가하며, 위장관 출혈, 궤양 및 천공 등 심각한 위장관계 이상반응이 나타날 수 있습니다.', '이 약에 과민증 환자, 위장관궤양, 위장관출혈, 심한 혈액이상, 심한 간장애, 심한 신장장애, 심한 심장기능부전, 심한 고혈압, 기관지천식, 아스피린 또는 다른 소염진통제에 의한 천식, 두드러기, 알레르기 반응 경험 환자, 심장동맥 우회로술 전후 통증발생 환자, 임신 말기 3개월 기간의 임부, 수유부, 항암요법으로 고용량 메토트렉세이트를 투여 중인 환자, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
권장용량을 초과하여 복용하지 마십시오.
이 약을 복용하기 전에 혈액이상, 출혈경향 환자, 간경화, 간장애, 신장장애, 심장기능부전, 심질환, 고혈압, 전신홍반루푸스, 혼합결합조직질환, 궤양성대장염, 크론병, 노인, 만 2세 미만의 소아, 임부, 수유부, 저용량 아스피린을 복용하는 사람, 수두인 경우 의사 또는 약사와 상의하십시오.
감기에 복용할 경우에는 원칙적으로 5일 이내로 복용하며 의사 또는 약사의 지시 없이 통증에 10일 이상(성인) 또는 5일 이상(소아) 복용하지 않고 발열에 3일 이상 복용하지 않습니다.', '항암요법으로 고용량 메토트렉세이트를 투여중인 환자, 다른 비스테로이드성 소염진통제와 함께 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 저용량 아스피린, ACE 저해제 복용자, 리튬, 푸로세미드 및 티아지드계 이뇨제, 저용량 메토트렉세이트, 쿠마린계 항응혈제(와파린 등), 선택적 세로토닌 재흡수억제제를 복용하는 환자는 의사 또는 약사와 상의하십시오.', '쇽 증상(호흡곤란, 혈압저하 등), 헤마토크리트감소, 헤모글로빈감소, 빈혈, 재생불량성빈혈, 용혈성빈혈, 무과립구증, 과립구감소, 백혈구감소, 혈소판감소, 혈소판기능저하, 호산구증가 등의 혈액장애, 소화성궤양, 위장관궤양, 위장출혈, 천공(뚫림), 궤양성대장염, 혈변, 위염, 췌장염, 혈액구토, 크론병, 식욕부진, 구역, 구토, 복통, 소화불량, 설사, 위부불쾌감, 상복부통증, 구갈, 구내염, 복부팽만감, 구강궤양, 변비, 흑변, 피부점막안증후군(스티븐스-존슨증후군), 독성표피괴사용해, 빈도불명의 호산구증가 및 전신 증후군을 동반한 약물 발진, 혈관신경성 부종, 수포성피부염, 다형홍반, 반구진 발진, 피부 붉어짐, 물집, 발진, 급성전신발진물집증, 간염, 황달, 간기능이상, 간장애, 과민증 또는 아나필락시스 반응, 천식발작, 두드러기, 습진, 자주색반점, 시각장애, 귀먹음, 귀울림, 미각이상, 현기증, 졸음, 어지러움, 우울, 두통, 뇌혈관사고 또는 신경질, 무균성수막염 또는 수막염(심한 두통, 구역, 구토, 불면, 목이 뻣뻣함, 발열 또는 의식장애), 혈압저하, 혈압상승, 심계항진(두근거림), 심부전, 심근경색증 또는 협심증, 코니스 증후군, 급성신부전, 소변감소, 혈뇨, 요단백, BUN, 혈중크레아티닌의 상승, 고칼륨혈증, 간질성 콩팥염, 콩팥염증후군, 콩팥유두괴사, 요량감소, 전신부종 및 이에 수반하는 숨가쁨, 나른함, 눈주변부기, 얼굴부기, 권태감, 발열, 코피, 부기, 말초부종 등이 나타나는 경우 즉각 복용을 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=197700120');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('197700120', '이부프로펜', NULL) ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('201908533', '탁센엠지연질캡슐', '(주)녹십자', '해열진통소염', '이 약은 두통, 치통, 발치후 동통(통증), 인후(목구멍)통, 귀의 통증, 관절통, 신경통, 요통, 근육통, 견통(어깨결림), 타박통, 골절통, 염좌통(삠통증), 월경통(생리통), 외상통의 진통 오한, 발열시의 해열에 사용합니다.', '만 15세 이상 및 성인은 1회 1~2캡슐, 1일 1~3회(복용간격은 4시간 이상), 만 11세 이상~만 15세 미만은 1회 1캡슐, 1일 1~3회(복용간격은 4시간 이상), 만 8세 이상~만 11세 미만은 1회 1캡슐, 1일 1~2회(복용간격은 6시간 이상) 공복(빈속)시를 피하여 복용합니다.', '매일 세 잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.
조절되지 않는 고혈압, 울혈심부전증, 확립된 허혈성 심장질환, 말초동맥질환, 뇌혈관질환을 가진 환자들은 신중히 고려하여 이부프로펜을 사용하고 고용량 이부프로펜(1일 2,400 mg)의 사용을 피하십시오. 또한, 심혈관계 위험 요소(예: 고혈압, 고지혈증, 당뇨병, 흡연)를 가지고 있는 환자가 고용량 이부프로펜(1일 2,400 mg)이 필요한 경우 장기간 치료를 시작하기 전 신중히 고려하십시오. 임상연구 결과, 고용량(1일 2,400 mg) 이부프로펜 사용이 동맥 혈전 증상(심근경색증 또는 뇌졸중)에 대한 위험성을 다소 증가시킬 수 있다고 나타났습니다.', '이 약에 과민증 환자, 이 약 또는 다른 해열진통제, 감기약 복용 시 천식 경험자, 만 1세 미만의 영아는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 수두 또는 인플루엔자에 감염되어 있거나 또는 의심되는 영아(갓난아기) 및 만 15세 미만의 어린이, 만 3개월 이상 만 1세 미만의 영아, 알레르기 체질, 알레르기 증상(발열, 발진, 관절통, 천식, 가려움증 등) 경험자, 간장질환, 신장(콩팥)질환, 갑상선질환, 당뇨병, 고혈압 등이 있는 사람, 몸이 약한 사람 또는 고열이 있는 사람, 고령자, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 속쓰림, 위부불쾌감, 위통과 같은 위장문제가 지속 혹은 재발되거나 궤양, 출혈문제를 가지고 있는 사람, 구토와 설사로 많은 수분을 손실하거나 수분을 흡수하지 않는 사람은 의사 또는 약사와 상의하십시오.
정해진 용법과 용량을 잘 지키십시오.
5~6회 복용하여도 증상의 개선이 없을 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '다른 해열진통제, 감기약, 진정제와 함께 복용하지 마십시오.
당뇨약, 통풍약, 관절염약, 항응고제, 스테로이드제, 이뇨제, 저용량 아스피린과 함께 복용 시 의사 또는 약사와 상의하십시오.
복용 중에는 음주하지 마십시오.', '발진·발적(충혈되어 붉어짐), 가려움, 구역, 구토, 식욕부진, 변비, 위통, 소화관출혈, 위부불쾌감(상복부 불쾌감), 어지러움, 부종(부기), 드물게 쇽(복용 후 바로 두드러기, 가슴답답함 등과 함께 안색이 창백하고, 손발이 차고, 식은땀, 숨쉬기 곤란함 등), 피부점막안증후군(스티븐스-존슨증후군), 독성표피괴사용해(리엘증후군), 천식, 매우 드물게 다형성 홍반, 탈락 피부염, 빈도불명의 광민감 반응, 호산구 증가 및 전신 증후군을 동반한 약물 반응(DRESS 증후군), 급성전신발진고름물집증, 빈도 불명의 코니스 증후군 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=201908533');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('201908533', '이부프로펜', NULL) ON CONFLICT DO NOTHING;
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('201908533', '메타규산알루민산마그네슘', '마그네슘') ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('200008591', '바이엘아스피린정500밀리그람', '바이엘코리아(주)', '해열진통소염', '이 약은 두통, 치통, 인후통, 생리통, 근육 및 관절의 통증, 요통, 경미한 관절염 통증의 증상 완화와 감기로 인한 통증 및 열 증상의 완화에 사용합니다.', '성인 및 만 15세 이상은 1회 1~2정(500~1,000 mg)을 최소 4시간 이상 간격으로 복용합니다.
1일 최대 용량으로서 8정(4,000 mg)을 초과하지 않도록 합니다.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.', '이 약 또는 살리실산 제제에 과민증 환자, 소화성 궤양, 아스피린 천식(비스테로이드성 소염진통제 등에 의한 천식발작의 유발) 또는 그 경험자, 환자혈우병, 중증의 간장애, 중증의 신장애, 중증의 심기능부전, 출혈경향이 있는 환자, 메토트렉세이트 15밀리그람(15 mg/주) 이상의 용량을 병용 투여하는 환자, 임신 3기에 해당하는 임부는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 신장애, 심혈관순환기능이상 환자(신혈관 질환, 울혈성 심부전, 체액 감소, 큰 수술, 패혈증 또는 주요 출혈 사고 등), 간장애, 심기능이상 환자, 혈액 이상 또는 그 경험자, 기관지천식, 수술전의 환자, 고령자, 중증 포도당-6-인산염 탈수소효소결핍증 환자, 만 15세 미만의 수두 또는 인플루엔자 환자는 의사 또는 약사와 상의하십시오.', '메토트렉세이트 15밀리그람(15 mg/주) 이상의 용량, 다른 비스테로이드성 소염진통제 및 살리실산 제제와 함께 사용하지 마십시오.
항응고제, 혈전용해제 또는 다른 혈소판응집억제제, 지혈제 및 당뇨병치료제(인슐린제제, 톨부타미드 등), 요산배설촉진제(벤즈브로마론, 프로베네시드), 저용량의 메토트렉세이트, 아세틸살리실산(아스피린), 리튬제제, 이부프로펜, 선택적 세로토닌 재흡수 억제제, 디곡신, 전신 작용 부신피질호르몬 제제(애디슨병 대체요법용 히드로코티손 제외), 안지오텐신 전환 효소 억제제, 발프로산을 복용하는 환자는 의사 또는 약사와 상의하십시오.', '쇽 증상(호흡곤란, 전신홍조, 혈관부종, 두드러기 등), 홍반, 가려움, 코막힘, 심장-호흡기 장애, 때때로 발진, 부종, 두드러기, 비염양 증상, 결막염, 드물게 리엘증후군(독성표피괴사용해), 열, 발진, 림프절 병증, 얼굴 종창, 간염, 신장염, 혈액학적 이상, 심근염, 근육염 등의 호산구 증가 및 전신 증상 동반 약물 반응(DRESS 증후군), 스티븐스-존슨증후군(피부점막안증후군), 박탈성 피부염, 재생불량성빈혈, 빈혈, 백혈구감소, 혈소판감소, 혈소판기능 저하(출혈시간의 지연), 식욕부진, 가슴쓰림, 위통, 구역, 구토, 위장출혈, 소화성궤양 및 뚫림(천공), 귀울림, 귀 먹음, 어지러움, 두통, 흥분, 간장애, 신장애, 급성 신부전, 과호흡, 대사성 산증 증상, 코니스 증후군 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200008591');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('200008591', '아스피린', NULL) ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('200108429', '아스피린프로텍트정100밀리그람', '바이엘코리아(주)', '해열진통소염', '이 약은 심근경색, 뇌경색, 불안정형 협심증에서 혈전 생성 억제와 관상동맥 우회술(CABG) 또는 경피경관 관상동맥 성형술(PTCA) 후 혈전 생성 억제와 고위험군환자(허혈성 심장질환의 가족력, 고혈압, 고콜레스테롤혈증, 비만, 당뇨 등 복합적 위험인자를 가진 환자)에서 심혈관계 위험성 감소에 사용합니다.', '성인은 1회 1정, 1일 1회 복용합니다.
이 약은 장용정이므로 충분한 물과 함께 식전에 복용할 수 있습니다.', '', '이 약 또는 다른 살리실산 제제에 과민증 환자, 소화성 궤양, 아스피린 천식 또는 경험자, 혈우병, 심한 간장애, 심한 신장애, 심한 심기능부전, 출혈경향, 일주일 동안 메토트렉세이트 15밀리그람(15 mg/주) 이상의 용량을 병용 투여하는 환자, 임신 3기에 해당하는 임부는 복용하지 마십시오.
임신 1기와 2기에는 반드시 필요한 경우가 아니라면 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 신장애, 심혈관 순환기능이상(신혈관 질환, 울혈성 심부전, 체액 감소, 큰 수술, 패혈증 또는 주요 출혈 사고 등), 간장애 또는 경험자, 심기능 이상, 혈액 이상 또는 경험자, 기관지천식, 수술전의 환자, 3세 이하의 유아, 진통제, 소염제, 항류마티스제에 과민증 및 알레르기 질환 환자, 고령자, 포도당-6-인산염 탈수소효소(G6PD)결핍 환자, 레이증후군, 14세 이하의 수두 또는 인플루엔자 감염 환자, 통풍환자는 의사 또는 약사와 상의하십시오.
출혈의 위험이 있으므로 수술(치과수술 포함)을 하는 경우에는 의사에게 이 약을 복용하고 있음을 알리십시오.
이 약의 장용피막을 파손하지 않도록 유의하십시오.', '비스테로이드성 소염진통제, 고용량의 메토트렉세이트(15mg/주 이상)은 이 약과 병용 투여 시 출혈이 증가되거나 신기능이 감소될 수 있으므로 함께 사용하지 않습니다.
항응고제, 혈전용해제, 다른 혈소판응집억제제, 지혈제, 당뇨병치료제(인슐린제제, 톨부타미드 등), 요산배설촉진제(벤즈브로마론, 프로베네시드), 저용량의 메토트렉세이트, 리튬제제, 이부프로펜, 나프록센 등 일부 비스테로이드성 소염진통제, 선택적 세로닌 재흡수 억제제, 디곡신, 전신 작용 부신피질호르몬 제제(애디슨병 대체요법용 히드로코티손 제외), 안지오텐신 전환 효소 억제제, 발프로산 제제를 복용하는 사람은 의사 또는 약사와 상의하십시오.
알칼리제제(예: 탄산수소나트륨, 탄산마그네슘) 또는 습기가 차기 쉬운 제제와 함께 섞지 마십시오.
알코올과 병용 투여 시 위장관 점막 손상이 증가하고, 이 약과 알코올의 상승효과로 인해 출혈시간이 연장될 수 있습니다.', '쇼크 및 아나필락시스 증상(호흡곤란, 전신홍조, 혈관부종, 두드러기), 천식발작, 과민증(홍반, 간지러움, 코막힘, 심장-호흡기 장애, 때때로 발진, 부종, 두드러기, 비염양 증상, 결막염), 드물게 독성표피괴사용해(라이엘증후군), 열, 발진, 림프절 병증, 얼굴 종창, 간염, 신장염, 혈액학적 이상, 심근염, 근육염 등의 호산구 증가 및 전신 증상 동반 약물 반응(DRESS 증후군), 피부점막안증후군(스티븐스-존슨증후군), 박탈성 피부염, 재생불량성빈혈, 빈혈, 백혈구감소, 혈소판감소, 혈소판기능 저하(출혈시간의 지연), 중증의 포도당-6-인산염 탈수소효소(G6PD) 결핍 환자에서의 용혈 및 용혈성 빈혈, 식욕부진, 가슴쓰림, 위통, 구역, 구토, 식욕부진, 가슴쓰림, 위통, 구역, 구토, 귀에서 소리가 남, 귀 먹음, 어지러움, 두통, 흥분, 드물게 간장애, 매우 드물게 일시적인 간손상, 신장애, 급성신부전, 과호흡, 대사성 산증, 빈도불명의 코니스 증후군(관상동맥 수축과 관련이 있는 알레르기 또는 과민증 후 발생하는 심혈관계 증상), 과도한 체온강하, 허탈, 사지냉각 등이 나타나는 경우 즉시 복용을 중지하고 의사 또는 약사와 상의하십시오.', '습기를 피해 실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200108429');
