INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('201503959', '콜대원콜드시럽', '대원제약(주)', '감기', '이 약은 감기의 여러 증상(콧물, 코막힘, 재채기, 기침, 가래, 인후(목구멍)통, 오한(춥고 떨리는 증상), 발열, 두통, 관절통, 근육통)의 완화에 사용합니다.', '만 15세 이상은 1회 1포(20 mL), 만 11세 이상~만 15세 미만은 1회
