INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('200905692', '클라리틴정(로라타딘)', '바이엘코리아(주)', '알레르기', '이 약은 알레르기성 비염(재채기, 코막힘, 가려움, 눈의 작열감(화끈감)), 만성 특발성(원인 불명의) 두드러기에 사용합니다.', '성인 및 체중 30kg 이상인 만 6세 이상의 소아는 1회 1정(10 mg)씩, 1일 1회 복용합니다.
만 6세 미만 및/또는 체중 30kg 미만 소아는 의사 또는 약사와 상의하십시오.', '', '이 약에 과민증 환자, 만 6세 미만의 소아, 임부 및 수유부, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 간장애, 신부전 환자는 의사 또는 약사와 상의하십시오.', '이 약을 복용하는 동안 시메티딘, 에리트로마이신, 케토코나졸, 퀴니딘, 플루코나졸, 플루옥세틴, 간 대사를 억제하는 약물을 함께 복용하지 마십시오.', '진정작용, 항콜린작용, 두통, 실신, 졸음, 목마름, 위장장애(구역, 위염), 식욕증진, 빈맥, 피로, 발진, 탈모증, 혈관부종을 포함한 아나필락시스, 간기능 장애, 상실성 부정빈맥, 두근거림, 어지러움, 경련 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.
