INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('199801016', '알레그라정120밀리그람(펙소페나딘염산염)', '(주)한독', '알레르기', '이 약은 알레르기비염 증상 완화에 사용합니다.', '성인 및 12세 이상 청소년은 1일 1회 120 mg을 식사전 물과 함께 복용합니다.
신부전 환자는 시작용량으로서 1일 1회 60 mg을 식사전 물과 함께 복용합니다.', '', '이 약에 과민증 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 신부전 환자, 고령자, 심혈관질환 환자 또는 경험자, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 저체중신생아, 신생아, 12세 미만의 소아는 의사 또는 약사와 상의하십시오.', '케토코나졸이나 에리트로마이신, 알루미늄, 수산화마그네슘을 함유한 제산제, 아팔루타마이드와 같은 P-gp 유도제와 함께 사용 시 의사 또는 약사와 상의하십시오.
자몽주스, 오렌지 및 사과주스와 같은 과일주스와 함께 복용 시 이 약의 효과를 감소시킬 수 있으므로 물과 함께 복용하는 것을 권장합니다.', '쇽 증상(호흡곤란, 혈압저하, 혈관부종, 가슴통증, 홍조 등), AST, ALT, γ-GTP, ALP, LDH 상승 등의 간기능장애, 황달이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.
두통, 졸음, 어지러움, 구역, 피로, 불면증, 신경과민증, 수면장애, 악몽, 발진, 발적, 두드러기, 가려움, 빈맥, 심계항진, 설사가 나타날 수 있습니다.', '실온에서 보관하십시오.
