INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('200801645', '개비스콘더블액션현탁액', '(유)옥시레킷벤키저', '소화위장', '이 약은 산 역류, 속쓰림, 위 내용물의 역류로 인한 소화불량(예를 들어 식사 후, 임신 중, 역류성 식도염과 동반하는 경우)개선에 사용합니다.', '성인 및 12세 이상의 소아는 1회 10~20 mL을 1일 4회(식후 및 취침전) 복용합니다.', '', '이 약에 과민증 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 울혈심부전, 신장애, 고칼슘혈증, 신석회침착증과 재발성 칼슘함유 신결석 환자, 12세 미만의 어린이는 의사 또는 약사와 상의하십시오.
1주일 정도 복용하여도 증상의 개선이 없을 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '테트라사이클린, 디곡신, 플루오로퀴놀론, 철염(Iron salt), 케토코나졸, 신경이완, 티록신, 페니실라민, 베타차단제(아테놀올, 메토프로롤, 프로프라놀롤), 글루코코르티코이드, 클로로퀸, 에스트라무스틴 및 디포스포네이와 함께 복용 시 의사 또는 약사와 상의하십시오.', '가려움이나 기관지 수축, 아나필락시스 반응과 같은 알레르기 반응 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '빛을 피해 실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200801645');
