INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('199400883', '겔포스엠현탁액', '(주)보령', '소화위장', '이 약은 위산과다(위염, 위·십이지장궤양에 관련된 것도 포함), 속쓰림, 위부불쾌감, 위부팽만감, 체함, 구역, 구토, 위통, 신트림에 사용합니다.', '성인 1회 1포씩, 1일 3회 식간(식사 때와 식사 때 사이) 및 취침 시 복용합니다. 복용간격은 4시간 이상으로 합니다.', '', '3개월 미만의 영아는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 1세 미만의 영아, 신장애 환자는 의사 또는 약사와 상의하십시오.
정해진 용법과 용량을 잘 지키십시오.', '테트라사이클린계 항생제를 함께 복용하지 마십시오.', '변비 또는 설사 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=199400883');
