INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('202104023', '속청큐액', '(주)종근당', '소화위장', '이 약은 식욕감퇴(식욕부진), 위부팽만감, 소화불량, 과식, 체함, 구역, 구토에 사용합니다.', '만 15세 이상 및 성인은 1회 1병씩, 만 11세 이상~만 15세 미만은 2/3병씩, 만 8세 이상~만 11세 미만은 1/2병씩, 만 5세 이상~만 8세 미만은 1/3병씩, 만 3세 이상~만 5세 미만은 1/4병씩, 만 1세 이상~만 3세 미만은 1/5병씩, 1일 3회 식후에 복용합니다.
복용간격은 4시간 이상으로 합니다.', '', '만 3개월 미만의 젖먹이는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 만 1세 미만의 젖먹이, 임부 또는 임신하고 있을 가능성이 있는 여성은 의사 또는 약사와 상의하십시오.
정해진 용법과 용량을 잘 지키십시오.
