INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('197400246', '마그밀정(수산화마그네슘)', '삼남제약(주)', '변비설사', '이 약은 위·십이지장궤양, 위염, 위산과다의 제산작용 및 증상의 개선, 변비증에 사용합니다.', '위.십이지장궤양, 위염, 위산과다에는 산화마그네슘으로서 1일 2~5정(1~2.5 g)을 수회(여러 차례) 분할 복용, 변비증에는 1일 2~4정(1~2 g)을 1~2회 분할 복용합니다.
연령, 증상에 따라 적절히 증감합니다.', '', '신장애, 설사 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 심기능 장애, 고마그네슘혈증 환자는 의사 또는 약사와 상의하십시오.', '테트라사이클린계 항생물질을 함께 복용하지 마십시오.
다량의 우유, 칼슘제제와 함께 복용 시 우유 알칼리 증후군(고칼슘혈증, 고질소혈증, 알칼리증 등)이 나타날 수 있으므로 의사 또는 약사와 상의하십시오.', '마그네슘 중독증상, 때때로 설사 등이 나타날 수 있습니다.', '습기와 빛을 피해 실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=197400246');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('197400246', '수산화마그네슘', '마그네슘') ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('201405042', '메이킨큐장용정', '명인제약(주)', '변비설사', '이 약은 변비와 변비에 수반하는 식욕부진(식욕감퇴), 복부(배부분)팽만, 장내이상발효, 치질의 완화에 사용합니다.', '만 15세 이상은 1회 1~3정씩, 만 11세 이상 ~ 만 15세 미만은 1회 1~2정씩, 1일 1회 취침 시에 복용합니다.
다만, 초회는 최소량을 복용하고 변의 모양과 상태를 보면서 조금씩 증량 또는 감량합니다.', '', '급성 복부질환(충수염, 장출혈, 궤양성 결장염 등) 환자, 장폐색(창자막힘) 환자, 만 7세 이하의 어린이는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 심한 복통(배 아픔) 또는 구역, 구토 환자, 임부 또는 임신하고 있을 가능성이 있는 여성, 나트륨 제한 식이를 하는 사람, 직장의 출혈 혹은 장부전의 경험이 있는 사람, 황색4호 또는 황색5호에 과민증 환자, 만 10세 이하의 어린이는 의사 또는 약사와 상의하십시오.
정해진 용법과 용량을 잘 지키십시오.
어린이에게 투여할 경우 보호자의 지도 감독하에 투여하십시오.
복용 시 정제를 씹지 마십시오.
1주 정도 투여하여도 변비의 개선이 없을 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '제산제 또는 우유 섭취 후 1시간 이내에 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 다른 약물을 복용하는 경우 의사 또는 약사와 상의하십시오.', '발진ㆍ충혈되어 붉어짐, 가려움, 심한 복통(배 아픔), 설사, 구토, 복부불쾌감, 경련이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=201405042');
