INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('198400661', '아락실과립', '부광약품(주)', '변비설사', '이 약은 변비와 변비에 수반하는 식욕부진(식욕감퇴), 복부(배부분)팽만, 장내이상발효, 치질의 완화에 사용합니다.', '성인 및 15세 이상의 소아는 1회 4 g~ 8 g을 1일 1회(저녁) 또는 2회(아침 및 저녁) 복용하되, 씹지말고 통상 아침에는 냉수, 저녁에는 온수로 복용합니다.
이 약을 취침 직전이나 누워있는 동안 복용하지 마십시오.', '', '이 약에 과민증 환자, 급성 복부질환(충수염, 장출혈, 궤양성 결장염 등), 장폐색(창자막힘), 위장관 내 협착증 환자, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 심한 복통, 구역, 구토 환자는 의사 또는 약사와 상의하십시오.
정해진 용법과 용량을 잘 지키십시오.
수회 정도 복용하여도 변비의 개선이 없을 경우 복용을 중지하고 의사 또는 약사와 상의하십시오.', '강심배당체와 함께 복용 시 의사 또는 약사와 상의하십시오.', '복통, 설사, 구토가 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=198400661');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('198400661', '아기오락스 원료과립(Agiolax pregranules)', NULL) ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('200300583', '다이톱현탁액(디옥타헤드랄스멕타이트)', '삼아제약(주)', '변비설사', '이 약은 성인의 식도, 위·십이지장과 관련된 통증의 완화, 성인의 급·만성 설사에 사용합니다.', '성인은 1회 3 g을 1일 3회 복용합니다.
급성설사시의 초기 3일은 1일 용량을 2배로 증량할 수 있습니다.
식도염에는 식후에, 다른 적응증에는 식간에 복용합니다.', '', '소아, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 심한 만성 변비 환자, 장폐색(창자막힘) 경험자는 의사 또는 약사와 상의하십시오.
정해진 용법과 용량을 잘 지키십시오.
7일 이상 복용하여도 증상의 개선이 없을 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.
이 약은 흡착성이 있어 타 약물과 함께 복용할 경우 흡수율이나 흡수시간에 영향을 미칠 수 있으므로 간격을 두고 복용하는 것이 바람직합니다.
탈수증이 나타나는 경우에는 적절한 수액공급을 하십시오.', '', '복부팽만감, 구토, 변비, 두드러기, 발진, 가려움 및 혈관 부종 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200300583');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('200300583', '디옥타헤드랄스멕타이트', NULL) ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('201803204', '동성정로환에프정', '동성제약(주)', '변비설사', '이 약은 설사, 체함, 묽은 변, 토사에 사용합니다.', '만 15세 이상 및 성인은 1회 4정씩, 만 8세 이상 ~ 만 15세 미만은 1회 2정씩, 1일 3회 식후에 복용합니다.
복용간격은 4시간 이상으로 하십시오.', '', '만 7세 이하의 어린이는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 발열을 수반하는 설사, 혈변 또는 점액변이 계속되는 환자, 고령자(노인)는 의사 또는 약사와 상의하십시오.
정해진 용법과 용량을 잘 지키십시오.
어린이에게 투여할 경우 보호자의 지도 감독하에 투여하십시오.
1주 이상 계속하여 복용하지 마십시오.
수일 간 복용하여도 증상의 개선이 없을 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오', '', '식욕부진, 위부불쾌감 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=201803204');
