INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('200000218', '볼그레액(철아세틸트랜스페린)', '(주)종근당', '비타민미네랄', '이 약은 철 결핍성빈혈에 사용합니다.', '성인은 철로서 1회 40 mg, 1일 1~2회 식사 시간을 피하여 복용합니다.', '만 6세 이하의 어린이가 과량 복용시 철분 중독성 사망을 일으킬 수 있으므로 어린이의 손에 닿지 않는 곳에 보관하십시오.', '이 약에 과민증 환자, 12개월 미만의 영아, 혈색소증, 헤모시데린침착증, 철 이용 장애, 비철결핍성 빈혈, 골수 부족에 의한 빈혈, 용혈성 빈혈, 철 과잉증, 악성 빈혈 환자, 감염이나 종양으로 인한 철 결핍성빈혈, 만성췌장염, 간경변 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 소화성궤양, 만성궤양성대장염, 국한성 대장염 등의 위장질환, 심장ㆍ순환기계기능 장애, 발작성 야간 혈색소뇨증, 신장애, 저단백혈증 환자는 의사 또는 약사와 상의하십시오.
정해진 용법과 용량을 잘 지키십시오.
적절한 약효를 얻기 위해서는 식사와 시간을 띄어서 복용하는 것이 좋습니다.', '인산염, 칼슘염, 경구용 테트라사이클린계 항생제, 제산제와 함께 복용하지 마십시오.
이 약을 복용하기 전에 철 함유제제(철분제, MRI용 간장 조영제 등), 항알도스테론제, 트리암테렌, 퀴놀론계, 페니실라민, 네오마이신, 콜레스티라민, 췌장엑스 및 비타민 E, 디포스폰산 염류, 티록신, 세프디니르 제제, 200 mg 이상의 아스코르빈산(비타민 C)을 복용 시 의사 또는 약사와 상의하십시오.
녹차, 홍차 등 탄닌을 함유하는 차 및 우유ㆍ유제품은 복용 중, 복용 전후에는 피하십시오.', '두드러기, 가려움, 햇빛 노출시 피부 과민반응, 복부ㆍ위통증, 위 경련, 구토, 설사, 열, 혼수, 때때로 AST, ALT의 상승, 드물게 ALP 상승, 구역, 식욕부진, 변비, 흑변, 치아변색, 위부불쾌감 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200000218');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('200000218', '철아세틸트랜스페린', '철분') ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('202001517', '칼디원정', '경동제약(주)', '비타민미네랄', '이 약은 임신ㆍ수유기, 발육기, 노년기의 비타민 D의 보급과 뼈, 이의 발육불량, 구루병의 예방에 사용합니다.', '만 8세 이상 및 성인은 1회 1정씩, 1일 1회 복용합니다.', '', '이 약에 과민증 환자, 만 12개월 미만의 젖먹이, 고칼슘혈증(혈액 중에 칼슘이 과잉으로 존재하는 상태), 유육종증(원인을 알 수 없는 전신 염증질환), 신장질환, 신장결석, 심한 증상의 신부전 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 만 1세 미만의 젖먹이, 햇빛을 많이 보고 정상적인 식사를 하는 어린이, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 미숙아, 유아, 심장ㆍ순환기계기능 장애, 신장장애, 저단백혈증 환자, 강심배당체를 투여 중인 환자, 신장결석 경험자는 의사 또는 약사와 상의하십시오.
정해진 용법과 용량을 잘 지키십시오.
어린이에게 투여할 경우 보호자의 지도 감독하에 투여하십시오.
1개월 이상 복용하여도 증상의 개선이 없을 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '인산염, 칼슘염, 경구용 테트라사이클린계 제제, 제산제와 함께 복용하지 마십시오.
강심배당체, 항알도스테론제, 트리암테렌과 함께 복용 시 의사 또는 약사와 상의하십시오.
녹차, 홍차 등 탄닌을 함유하는 차는 복용 중, 복용 전후에는 피하십시오.', '구역, 구토, 설사, 변비, 저혈압, 얼굴달아오름, 심박동불규칙, 피부발진 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=202001517');
