INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('202001517', '농축콜레칼시페롤', '비타민D') ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('198100119', '우루사정100밀리그램(우르소데옥시콜산)', '(주)대웅제약', '간피로', '이 약은 담즙(쓸개즙)분비 부전으로 오는 간질환, 담도(쓸개길)(담관(쓸개관), 담낭(쓸개))계 질환의 보조 치료와 만성 간질환의 간기능 개선과 소장절제 후유증 및 염증성 소장 질환의 소화불량에 사용합니다.', '성인은 1회 0.5~1정(50~100 mg) 1일 3회 복용합니다.', '', '이 약에 과민증 환자, 심한 담도 폐쇄, 전격성간염, 방사선비투과성 석회화된 담석, 비기능성 담낭, 급성 담낭염, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 소아, 신질환, 소화성궤양(급성 위ㆍ십이지장 궤양), 크론병과 같은 대장 및 소장염, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 심한 췌장(이자), 담석증, 정맥류 출혈, 간성혼수, 복수(뱃물), 간이식이 필요한 환자는 의사 또는 약사와 상의하십시오.', '경구용 당뇨병제(톨부타미드), 콜레스티라민, 콜레스티폴, 약용탄, 마그네슘 및 수산화알루미늄을 함유하는 제산제, 간에서 콜레스테롤 분비를 증가시키는 약물(에스트로겐 함유 경구용 피임제, 클로피브레이트와 같이 지질감소약물), 간에 손상을 주는 약물을 함께 복용하지 마십시오.', '때때로 설사, 구역, 구토, 드물게 배 아픔, 변비, 가슴쓰림, 위부불쾌감, 때때로 가려움, 드물게 발진, 발열, 기침, 호흡곤란, 흉부 X선 이상을 동반한 간질성 폐렴, 드물게 전신권태감, 어지럼, 담석의 석회화, 간효소치의 증가(ALT, ALP, AST, γ-GT), 백혈구 감소가 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=198100119');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('198100119', '우르소데옥시콜산', NULL) ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('200300913', '이가탄에프캡슐', '명인제약(주)', '잇몸', '이 약은 치주치료 후 치은염, 경·중등도 치주염의 보조치료에 사용합니다.', '성인은 1회 1캡슐, 1일 3회 식후에 복용합니다.', '', '15세 미만의 소아, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 약 및 화장품에 알레르기 증상(발진, 발적, 가려움 등) 경험자, 달걀에 알레르기 증상(발열, 발진, 관절통, 천식, 가려움 등) 경험자, 알레르기 체질인 사람, 황색5호에 과민증 환자 또는 경험자는 의사 또는 약사와 상의하십시오.
정해진 용법과 용량을 잘 지키십시오.', '이 약을 복용하기 전에 다른 약물을 복용하고 있는 경우 의사 또는 약사와 상의하십시오.', '발진, 발적, 설사, 식욕부진, 위부불쾌감, 구역, 구토, 구내염, 피부점막안증후군(스티븐스-존슨증후군) 또는 독성표피괴사용해(리엘증후군)의 증상(예: 발열, 홍반, 가려움, 안충혈, 구내염 등의 증상, 전신의 피부, 입과 목의 점막에 고열을 동반하는 발진·발적, 화상모양의 수종 등의 중증의 증상) 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200300913');
