INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('198900711', '아론정(독시라민숙신산염)', '알리코제약(주)', '수면멀미', '이 약은 불면증의 보조치료 및 진정에 사용합니다.', '성인은 1일 1회 1정(25 mg)을 반드시 수면 30분 전에 복용합니다.
연령과 증상에 따라 적절히 증감할 수 있습니다.', '', '폐기종, 만성 기관지염 천식 등의 호흡장애, 녹내장, 전립선(전립샘) 비대 환자, 수유부, 15세 이하의 소아, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 임부 및 임신을 하고 있을 가능성이 있는 사람은 의사 또는 약사와 상의하십시오.
복용 후 과도한 진정이 나타날 수 있으므로 운전 및 기계조작 시 주의하십시오.
의사 또는 약사와 상의 없이 2주 이상 투여하지 마십시오.', '이 약을 복용하는 동안 이미프라민계 항우울약, 항파킨슨제, 디소피라미드와 함께 복용하지 마십시오.
복용 중에는 음주하지 마십시오.', '때때로 항콜린작용이 나타날 수 있습니다.', '빛을 피해 실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=198900711');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('198900711', '독시라민숙신산염', NULL) ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('200807310', '슬리펠정25밀리그램(디펜히드라민염산염)', '한미약품(주)', '수면멀미', '이 약은 일시적 불면증의 완화에 사용합니다.', '성인은 1회 2정(50 mg)씩, 1일 1회 취침 전에 복용합니다.
개인에 따라 과도한 진정작용이 나타날 경우 1회 1정(25 mg)씩 복용합니다.', '', '이 약에 과민증, 천식발작, 폐기종, 만성기관지염에 의한 호흡곤란, 녹내장, 전립선 비대 등 하부 요로 폐색성 질환, 협착성 소화성 궤양 또는 유문십이지장 폐색 환자, 15세 미만의 소아, 뇌전증 등의 경련성 질환, 크롬친화성세포종 환자, 수유부, 일상적 불면, 불면증 진단, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당·갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 중증 근무력증 환자, 고령자, 알레르기 체질, 약에 의한 알레르기 증상 경험자, 임부 또는 임신하고 있을 가능성이 있는 여성은 의사 또는 약사와 상의하십시오.
복용 후 졸음이 나타날 수 있으므로 운전 및 기계조작 시 주의하십시오.
정해진 용법과 용량을 잘 지키십시오.
2~3회 복용하여도 증상의 개선이 없을 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '이 약과 동일한 성분의 다른 제제, 다른 최면진정제, MAO억제제, 감기약, 해열진통제, 진해거담약, 항히스타민제를 함유하고 있는 내복약(비염용 내복약, 멀미약, 알러지용약)과 함께 복용하지 마십시오.
복용 중에는 음주하지 마십시오.', '발진, 발적, 가려움, 구갈, 위통, 오심ㆍ구토, 식욕부진, 설사, 어지러움, 두통, 기상시의 두중감, 활동중의 졸음, 불쾌감, 신경과민, 일시적인 의식장해(주의력의 저하, 잠이 덜깨는 증상, 판단력의 저하, 말ㆍ행동의 이상 등), 두근거림, 권태감, 배뇨곤란, 시야혼란, 폐쇄각 녹내장 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200807310');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('200807310', '디펜히드라민염산염', NULL) ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('199800924', '토스롱액', '동성제약(주)', '수면멀미', '이 약은 멀미에 의한 어지러움, 구토, 두통의 예방 및 완화에 사용합니다.', '멀미의 예방에는 승차 30분 전에 1회 복용량을 복용합니다.
연령구분에 따른 1회 복용량은 만 15세 이상은 1병(30 mL), 만 11세 이상~만 15세 미만은
2
/
3
병(20 mL), 만 7세 이상~만 11세 미만은
1
/
2
병(15 mL), 만 3세 이상~만 7세 미만은
1
/
3
병(10 mL)입니다.
필요시 추가 복용할 경우에는 1회 복용량을 4시간 이상의 간격을 두고 복용하며 1일 복용횟수는 2회를 한도로 합니다.', '', '수유부, 만 3세 미만의 영 · 유아는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 알레르기 증상(발진, 충혈되어 붉어짐, 가려움 등) 경험자, 임부 또는 임신하고 있을 가능성이 있는 여성, 수유부, 녹내장(눈의 통증, 눈의 침침함 등), 배뇨(소변을 눔)장애, 심장장애, 허약자, 노인, 폐기종 혹은 만성 기관지염과 같은 호흡기질환 환자, 황색5호 성분에 과민증 환자는 의사 또는 약사와 상의하십시오.
정해진 용법과 용량을 잘 지키십시오.
어린이에게 투여할 경우 보호자의 지도 감독하에 투여하십시오.
이 약 복용 후 졸음이 나타날 수 있으므로 운전 및 기계조작 시 주의하십시오.', '다른 진토제, 감기약, 해열진통제, 항히스타민제, 진정제, 진해거담제, 위장진통·진경제와 함께 복용하지 마십시오.
복용 중에는 알코올성 음료를 피하십시오.', '발진, 충혈되서 붉어짐, 가려움, 두통, 안면홍조, 눈부심, 배뇨(소변을 눔)장애, 구갈(목마름) 또는 변비 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=199800924');
