INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('201104297', '니코레트인비지패취(니코틴)', '켄뷰코리아판매유한회사', '금연', '이 약은 금연시 보조 요법제로 사용합니다.', '매일 아침에 일어나자마자 패취 1매를 부착하고 취침 시에 떼어냅니다.깨끗하게 씻은 손으로 패취의 박리지 한쪽을 떼어내고 털이 없는 피부의 건조하고 손상되지 않은 부위 (엉덩이, 상완, 가슴 등)에 부착하고 나머지 박리지를 떼어내어 완전히 부착합니다.권장용량과 권장기간은 허가사항을 참고하십시오.', '이 약 사용 중에 담배를 계속 피우면 니코틴에 의하여 심혈관 부작용이 더 자주, 더 뚜렷하게 나타날 수 있으므로 완전히 금연한 환자만 사용하십시오.', '이 약에 과민증 환자, 만성피부질환(건선, 만성피부염, 두드러기), 전신적인 피부질환, 과민성피부염, 불안정 협심증, 협심증 악화, 최근 3개월 이내에 심근경색을 경험한 환자, 급성 경색증 후기, 중증의 심부정맥, 전신 고혈압, 말초혈관질환, 뇌혈관질환(급성 뇌졸중, 뇌혈관 이상), 임부 및 수유부, 18세 미만의 소아 및 청소년, 비흡연자 및 일시적 흡연자는 이 약을 사용하지 마십시오.
이 약을 사용하기 전에 위염, 소화성궤양, 폐색성 동맥질환, 안정형 협심증, 심부전, 비대상성 심부전, 심근경색, 심부정맥, 혈관경련, 조절되지 않는 고혈압, 동맥혈관 바이패스 이식 또는 혈관성형술 환자, 신부전, 간부전, 당뇨병, 갑상선기능항진증, 크롬친화세포종 환자, 간질 또는 발작 병력이 있는 환자는 의사 또는 약사와 상의하십시오.', '파라세타몰, 카페인, 이미프라민, 옥사제팜, 펜타조신, 프로프라놀롤, 테오필린, 와파린, 에스트로겐, 리그노카인, 페나세틴, 인슐린, 아드레날린성 길항제(프라조신, 라베탈롤 등), 플레카이니드, 아드레날린성 효능제(이소프레날린, 페닐레프린), 프로폭시펜, 푸로세미드 이뇨제, H2길항제, 베타차단제, 타크린, 클로자핀, 로피니롤과 함께 사용 시 의사 또는 약사와 상의하십시오.', '홍반(붉은 반점), 작열감(화끈감), 수포, 피부 발진 또는 적용 부위의 조임, 초조, 불안, 신경과민, 불면, 비정상적 꿈, 두통, 어지러움, 운동이상, 주의력장애, 기면(졸음), 정서불안, 과민, 우울, 혼돈상태, 진전(떨림), 발작, 두근거림, 고혈압, 홍조, 가슴 통증, 호흡곤란, 부정맥, 기침, 상기도감염, 오심(구역), 복통(배아픔), 소화불량, 구토, 변비, 설사, 복부(배부분)팽만, 구강(입안) 건조, 적용부위 피부반응, 다한증(땀과다증), 피부 탈색, 경피혈관염, 적용부위 통증 및 불쾌감, 근육통, 관절염, 무력증, 관절통, 근 경축(경련과 수축이 일어나 수축상태가 지속되는 현상), 요통(허리통증), 두드러기, 발진, 가려움증, 혈관부종(부기), 아나필락시스양반응 등이 나타나는 경우 사용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 25℃ 이하에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=201104297');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('201104297', '니코틴', NULL) ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('202106054', '경동파니틴정10밀리그램(파모티딘)', '경동제약(주)', '소화위장', '이 약은 위산과다, 속쓰림, 신트림에 사용합니다.', '16세 이상 1회 1정(10 mg)씩, 1일 2정(20 mg)까지 복용할 수 있습니다.', '', '이 약 및 다른 H2 수용체 길항제에 과민증 환자, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 음식을 삼키기 어렵거나 삼킬 때 통증이 있는 경우 및 토혈(혈액구토)이나 혈변이 있는 경우, 속쓰림 증상이 3개월 이상 지속된 경우, 현기증(어지러움) 또는 졸림, 식은땀, 짧은 호흡과 함께 가슴 또는 어깨 통증, 가슴 통증이 빈번히 나타나는 경우, 예상치 않은 체중감소, 오심(구역), 구토, 위장관 통증, 약물들에 의한 과민증 환자, 신장애(신장장애), 심질환, 간장애 환자, 고령자(노인), 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 이 약을 투여 후 투약 전과 신체 기능에 변화가 있는 경우, 혈액투석환자는 의사 또는 약사와 상의하십시오.
증상 완화 목적으로 일시적으로만 사용하십시오.
14일 이상 복용하지 마십시오.', '이 약을 복용하기 전에 비스테로이드성 소염(항염)진통제, 무좀치료제 및 항진균제(이트라코나졸 및 포사코나졸 경구현탁액 등), 티로신 키나아제 억제제(다사티닙, 엘로티닙, 게피티니브, 파조파닙 등)를 복용하는 환자는 의사 또는 약사와 상의하십시오.
알코올이 함유된 음료와 함께 복용하지 마십시오.', '증상이 지속되거나 악화되는 경우, 쇽, 아나필락시스, 호흡곤란, 전신홍조(온몸이 붉어짐), 안면부종(얼굴부기), 인두부종(부기), 두드러기, 백혈구 감소, 적혈구 감소, 혈소판감소(지혈지연과 동일한 의미), 호산구감소, 빈혈, 지혈지연(전신권태감, 무력, 피하(피부밑)점막하 출혈, 발열), 피부점막안증후군, 표피괴사증, 발진, 두드러기(홍반), 간기능 이상, AST(GOT)ㆍALT(GPT) 등의 상승, 총빌리루민ㆍLDH 상승, 황달, 간염, 근육통, 횡문근융해증(횡문근용해), 관절통, 근육경련, 서맥(느린맥), 빈맥(빠른맥), 가슴 통증, 혈압상승, 안면홍조, 이명(귀울림), 의식장애, 경련, 전신권태감, 두통, 졸음, 불면, 환각, 초조, 흥분, 성욕감퇴, 감각이상, 두중감(머리무거움), 혼돈, 우울, 어지러움, 변비, 설사, 구갈, 구역구토, 복부(배부분)팽만감, 식욕부진, 구내염(입안염), 간질성 신염(신장염), 급성 신부전, 발열, 신기능 검사치 이상(BUNㆍ크레아티닌 상승 등), 월경불순, 고열, 기침, 호흡곤란 및 흉부 X-ray 이상을 동반한 간질성 폐렴, 기관지경련, 여성형유방, 미각이상 등이 나타나는 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.
어린이의 손이 닿지 않는 곳에 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=202106054');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('202106054', '파모티딘', NULL) ON CONFLICT DO NOTHING;
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, source, source_url) VALUES ('202500070', '다이어스탑캡슐(로페라미드염산염)', '(주)씨엠지제약', '변비설사', '이 약은 급성설사, 만성설사에 사용합니다.', '성인은 급성설사인 경우, 2캡슐(4 mg)을 복용하고, 유지량으로는 묽은 변이 있을 때마다 1캡슐(2 mg)씩을 복용합니다. 1일 상용량은 3~4캡슐(6~8 mg)이며, 1일 최대복용량은 8캡슐(16 mg)입니다.
만성설사인 경우, 초회량은 2캡슐(4 mg)을 복용하고, 설사가 치료될 때까지 묽은 변이 있을 때마다 1캡슐(2 mg)을 복용합니다. 그 이후에는 환자 개별적으로 필요에 맞도록 용량을 감소시킵니다. 1일 최적투여량이 결정되면 이를 1일 1회 또는 1일 2회로 나누어 복용합니다. 보통 유지용량은 1일 1~3캡슐(2~6 mg)이며, 1일 최대용량은 8캡슐(16 mg)입니다.
9~12세의 소아는 급성설사에 1캡슐(2 mg)을 복용하고, 유지량으로는 묽은 변이 있을 때마다 1캡슐(2 mg)씩을 복용합니다. 1일 최대용량은 3캡슐(6 mg)입니다.
연령, 증상에 따라 적절히 증감할 수 있습니다.', '', '24세 미만의 영아, 소아(만성설사인 경우), 혈변 및 고열이 있는 세균성 설사, 급성 궤양성 대장염, 광범위 항생물질 투여와 관련된 위막성 대장염, 장폐색증, 거대결장증, 중독성거대결장증 등을 포함하는 중요한 후유증 위험의 가능성 때문에 연동억제를 피해야 하는 환자, 이 약에 과민증 경험자, 출혈성 대장염, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 간장애, AIDS 환자, 임부, 수유부, 24개월 이상 7세 이하의 영·유아, 고령자는 의사 또는 약사와 상의하십시오.
급성 설사의 경우 48시간 이내, 만성 설사의 경우 10일 이내 증상의 개선이 없을 경우 사용을 즉각 중지하고 의사 또는 약사와 상의하십시오.
체액 및 전해질 손실이 나타날 수 있으므로 적합한 수액 및 전해질을 보충해 주도록 합니다.
복용 후에 피로, 어지러움, 졸음이 나타날 수 있으므로 운전 또는 기계조작 시 주의하십시오.', '퀴니딘, 리토나비르와 함께 복용 시 의사 또는 약사와 상의하십시오.', '매우 드물게 발진, 두드러기, 소양감, 이례적으로 혈관부종, 독성표피괴사용해(리엘증후군), 다형성 홍반, 스티븐스-존슨증후군을 포함하는 수포성 발진, 아나필락시스 쇽, 매우 드물게 복통, 장폐색증, 복부팽만, 구역, 변비, 구토, 중독성 거대결장증을 포함하는 거대결장증, 고창, 소화불량, 빈도 불명의 급성췌장염, 이례적으로 뇨저류, 매우 드물게 졸음, 어지러움 등이 나타날 수 있습니다.', '실온에서 보관하십시오.', '식품의약품안전처 의약품안전나라 e약은요', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=202500070');
INSERT INTO drug_ingredient (item_seq, ingredient, nutrient) VALUES ('202500070', '로페라미드염산염', NULL) ON CONFLICT DO NOTHING;
