INSERT INTO substance (id, name, aliases, kind, is_vitamin, recommendable, function_claim, function_source_title, function_source_url, nutrient_keys, summary, display_name, upper_limit) VALUES ('metformin', '메트포르민', '["메트포르민염산염","metformin","글루코파지","글루코파지정","다이아벡스","다이아벡스정","글루파정"]'::jsonb, 'rx_ingredient', false, false, NULL, NULL, NULL, '[]'::jsonb, '전문의약품 성분. 의약품_전체목록.csv에서 주성분이 메트포르민염산염인 품목: 글루코파지정, 다이아벡스정, 글루파정.', NULL, NULL);

-- 조합 규칙 26개
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('202300436-calcium', 'drug', '202300436', 'substance', 'calcium', 'avoid', NULL, '인산염, 칼슘염, 경구용 테트라사이클린계 제제, 제산제, 레보도파와 함께 복용하지 마십시오.', NULL, '비맥스제트정과 칼슘제(칼슘염)를 함께 복용하지 않는다.', '비맥스제트정을 먹고 있는데 칼슘제를 같이 먹어도 되나요?', 'R7', '비맥스제트정 e약은요 (식약처 의약품안전나라)', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=202300436', 'mfds_easy_drug', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('levothyroxine-calcium', 'substance', 'levothyroxine', 'substance', 'calcium', 'separate_timing', '레보티록신 흡수 감소(단독 복용과 비교해 약 20%–25%)', 'Coadministration of each of the three calcium preparations significantly reduced levothyroxine absorption by about 20%–25% compared with levothyroxine given alone. It is therefore recommended that patients be cautioned to take their levothyroxine well separated from all of these calcium products.', '세 가지 칼슘 제제 각각을 함께 복용했을 때, 레보티록신을 단독으로 복용했을 때와 비교해 레보티록신 흡수가 약 20%–25% 유의하게 줄었다. 따라서 환자에게 레보티록신을 이들 칼슘 제품 모두와 충분히 띄워 복용하도록 주의시킬 것을 권고한다.', '레보티록신과 최소 4시간 띄워 드세요', '갑상선약(레보티록신)과 칼슘제를 4시간 띄워 먹으면 되나요?', 'R3', 'Absorption of Levothyroxine When Coadministered with Various Calcium Formulations (Thyroid, 2011)', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC3092723/', 'paper', '건강한 성인 8명 연구', '[{"source_id":"N1","source_title":"Levothyroxine (MedlinePlus)","source_url":"https://medlineplus.gov/druginfo/meds/a682461.html","source_kind":"other","source_note":null,"quote":"if you take calcium carbonate (Tums) or ferrous sulfate (iron supplement), take it at least 4 hours before or 4 hours after you take levothyroxine.","quote_ko":"탄산칼슘(Tums)이나 황산제일철(철분 보충제)을 복용한다면, 레보티록신 복용 최소 4시간 전 또는 4시간 후에 복용하십시오."}]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('calcium-iron', 'substance', 'calcium', 'substance', 'iron', 'caution', '철분 흡수 감소(칼슘 300-600 mg에서 50-60%)', 'We investigated the effect of calcium on iron absorption in 126 human subjects. Calcium also had a direct dose-related inhibiting effect on iron absorption, noted by adding calcium to the rolls after they had been baked instead of to the dough. Iron absorption was reduced by 50-60% at doses of 300-600 mg Ca.', '우리는 사람 126명을 대상으로 칼슘이 철분 흡수에 미치는 영향을 조사했다. 칼슘은 철분 흡수를 양에 비례해 직접 억제하는 효과도 있었는데, 이는 칼슘을 반죽이 아니라 다 구운 빵에 넣어 확인했다. 칼슘 300-600 mg에서 철분 흡수가 50-60% 줄었다.', '칼슘은 철분 흡수를 줄이므로, 칼슘과 철분제를 함께 먹을 때는 먹는 방법(시간 간격 등)을 약사와 상의한다.', '칼슘과 철분제를 같이 먹으면 철분 흡수가 줄어든다는데, 어떻게 나눠 먹어야 하나요?', 'R11', 'Calcium: effect of different amounts on nonheme- and heme-iron absorption in humans (American Journal of Clinical Nutrition, 1991, Hallberg 외)', 'https://agris.fao.org/search/en/records/65de38d263b8185d9ca7afd3', 'paper', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('200801645-iron', 'drug', '200801645', 'substance', 'iron', 'consult', NULL, '테트라사이클린, 디곡신, 플루오로퀴놀론, 철염(Iron salt), 케토코나졸, 신경이완, 티록신, 페니실라민, 베타차단제(아테놀올, 메토프로롤, 프로프라놀롤), 글루코코르티코이드, 클로로퀸, 에스트라무스틴 및 디포스포네이와 함께 복용 시 의사 또는 약사와 상의하십시오.', NULL, '개비스콘더블액션현탁액과 철분제를 함께 복용할 때는 의사 또는 약사와 상의한다.', '개비스콘(제산제)을 먹는데 철분제를 같이 먹어도 되나요?', 'R6', '개비스콘더블액션현탁액 e약은요 (식약처 의약품안전나라)', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200801645', 'mfds_easy_drug', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('198700430-iron', 'drug', '198700430', 'substance', 'iron', 'consult', NULL, '이 약을 복용하기 전에 비스테로이드소염(항염)진통제, 궤양치료제, 디기탈리스 제제, 클로르프로마진, 란소프라졸, 프레드니솔론, 페니실린, 퀴놀론, 철(Fe)염 제제, 살리실산염을 복용하는 환자는 의사 또는 약사와 상의하십시오.', NULL, '철분제를 먹고 있으면 알마겔정을 복용하기 전에 의사 또는 약사와 상의한다.', '철분제를 먹고 있는데 알마겔(제산제)을 같이 먹어도 되나요?', 'R6', '알마겔정(알마게이트) e약은요 (식약처 의약품안전나라)', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=198700430', 'mfds_easy_drug', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('197400246-calcium', 'drug', '197400246', 'substance', 'calcium', 'consult', '우유 알칼리 증후군(고칼슘혈증, 고질소혈증, 알칼리증 등)', '다량의 우유, 칼슘제제와 함께 복용 시 우유 알칼리 증후군(고칼슘혈증, 고질소혈증, 알칼리증 등)이 나타날 수 있으므로 의사 또는 약사와 상의하십시오.', NULL, '마그밀정과 칼슘제를 함께 복용할 때는 의사 또는 약사와 상의한다.', '변비약 마그밀을 먹는데 칼슘제를 같이 먹어도 되나요?', 'R6', '마그밀정(수산화마그네슘) e약은요 (식약처 의약품안전나라)', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=197400246', 'mfds_easy_drug', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('201206997-calcium', 'drug', '201206997', 'substance', 'calcium', 'avoid', NULL, '인산염, 칼슘염, 경구용 테트라사이클린계 제제, 제산제, 레보도파와 함께 복용하지 마십시오.', NULL, '삐콤씨정과 칼슘제(칼슘염)를 함께 복용하지 않는다.', '삐콤씨를 먹고 있는데 칼슘제를 같이 먹어도 되나요?', 'R6', '삐콤씨정 e약은요 (식약처 의약품안전나라)', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=201206997', 'mfds_easy_drug', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
