INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('201307920-calcium', 'drug', '201307920', 'substance', 'calcium', 'avoid', NULL, '인산염, 칼슘염, 경구용 테트라사이클린계 제제, 제산제, 레보도파와 함께 복용하지 마십시오.', NULL, '마그비연질캡슐과 칼슘제(칼슘염)를 함께 복용하지 않는다.', '마그비를 먹고 있는데 칼슘제를 같이 먹어도 되나요?', 'R6', '마그비연질캡슐 e약은요 (식약처 의약품안전나라)', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=201307920', 'mfds_easy_drug', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('201606593-calcium', 'drug', '201606593', 'substance', 'calcium', 'avoid', NULL, '인산염, 칼슘염, 경구용 테트라사이클린계 제제, 제산제, 레보도파와 함께 복용하지 마십시오.', NULL, '훼로바맘스케어정과 칼슘제(칼슘염)를 함께 복용하지 않는다.', '철분제 훼로바를 먹고 있는데 칼슘제를 같이 먹어도 되나요?', 'R6', '훼로바맘스케어정 e약은요 (식약처 의약품안전나라)', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=201606593', 'mfds_easy_drug', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('201700750-calcium', 'drug', '201700750', 'substance', 'calcium', 'avoid', NULL, '이 약을 복용하는 동안 인산염, 칼슘염, 경구용 테트라사이클린계 제제, 제산제, 레보도파를 복용하지 마십시오.', NULL, '헤모큐수정을 복용하는 동안 칼슘제(칼슘염)를 복용하지 않는다.', '철분제 헤모큐를 먹고 있는데 칼슘제를 같이 먹어도 되나요?', 'R6', '헤모큐수정 e약은요 (식약처 의약품안전나라)', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=201700750', 'mfds_easy_drug', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('200000218-calcium', 'drug', '200000218', 'substance', 'calcium', 'avoid', NULL, '인산염, 칼슘염, 경구용 테트라사이클린계 항생제, 제산제와 함께 복용하지 마십시오.', NULL, '볼그레액과 칼슘제(칼슘염)를 함께 복용하지 않는다.', '철분제 볼그레를 먹고 있는데 칼슘제를 같이 먹어도 되나요?', 'R6', '볼그레액(철아세틸트랜스페린) e약은요 (식약처 의약품안전나라)', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200000218', 'mfds_easy_drug', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('200000218-iron', 'drug', '200000218', 'substance', 'iron', 'consult', NULL, '이 약을 복용하기 전에 철 함유제제(철분제, MRI용 간장 조영제 등), 항알도스테론제, 트리암테렌, 퀴놀론계, 페니실라민, 네오마이신, 콜레스티라민, 췌장엑스 및 비타민 E, 디포스폰산 염류, 티록신, 세프디니르 제제, 200 mg 이상의 아스코르빈산(비타민 C)을 복용 시 의사 또는 약사와 상의하십시오.', NULL, '다른 철분제를 먹고 있으면 볼그레액을 복용하기 전에 의사 또는 약사와 상의한다.', '다른 철분제를 먹고 있는데 볼그레(철분제)를 같이 먹어도 되나요?', 'R6', '볼그레액(철아세틸트랜스페린) e약은요 (식약처 의약품안전나라)', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200000218', 'mfds_easy_drug', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('200000218-vitamin_e', 'drug', '200000218', 'substance', 'vitamin_e', 'consult', NULL, '이 약을 복용하기 전에 철 함유제제(철분제, MRI용 간장 조영제 등), 항알도스테론제, 트리암테렌, 퀴놀론계, 페니실라민, 네오마이신, 콜레스티라민, 췌장엑스 및 비타민 E, 디포스폰산 염류, 티록신, 세프디니르 제제, 200 mg 이상의 아스코르빈산(비타민 C)을 복용 시 의사 또는 약사와 상의하십시오.', NULL, '비타민E를 먹고 있으면 볼그레액을 복용하기 전에 의사 또는 약사와 상의한다.', '비타민E를 먹고 있는데 볼그레(철분제)를 같이 먹어도 되나요?', 'R6', '볼그레액(철아세틸트랜스페린) e약은요 (식약처 의약품안전나라)', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200000218', 'mfds_easy_drug', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('200000218-vitamin_c', 'drug', '200000218', 'substance', 'vitamin_c', 'consult', '200 mg 이상의 비타민C(아스코르빈산)를 함께 복용할 때 해당(원문은 결과를 직접 적지 않음)', '이 약을 복용하기 전에 철 함유제제(철분제, MRI용 간장 조영제 등), 항알도스테론제, 트리암테렌, 퀴놀론계, 페니실라민, 네오마이신, 콜레스티라민, 췌장엑스 및 비타민 E, 디포스폰산 염류, 티록신, 세프디니르 제제, 200 mg 이상의 아스코르빈산(비타민 C)을 복용 시 의사 또는 약사와 상의하십시오.', NULL, '비타민C를 200 mg 이상 먹고 있으면 볼그레액을 복용하기 전에 의사 또는 약사와 상의한다.', '비타민C를 하루 200 mg 넘게 먹고 있는데 볼그레(철분제)를 같이 먹어도 되나요?', 'R6', '볼그레액(철아세틸트랜스페린) e약은요 (식약처 의약품안전나라)', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200000218', 'mfds_easy_drug', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('202001517-calcium', 'drug', '202001517', 'substance', 'calcium', 'avoid', NULL, '인산염, 칼슘염, 경구용 테트라사이클린계 제제, 제산제와 함께 복용하지 마십시오.', NULL, '칼디원정과 다른 칼슘제(칼슘염)를 함께 복용하지 않는다.', '칼디원정을 먹고 있는데 칼슘제를 따로 더 먹어도 되나요?', 'R6', '칼디원정 e약은요 (식약처 의약품안전나라)', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=202001517', 'mfds_easy_drug', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('levothyroxine-iron', 'substance', 'levothyroxine', 'substance', 'iron', 'separate_timing', NULL, 'if you take calcium carbonate (Tums) or ferrous sulfate (iron supplement), take it at least 4 hours before or 4 hours after you take levothyroxine.', '탄산칼슘(Tums)이나 황산제일철(철분 보충제)을 복용한다면, 레보티록신 복용 최소 4시간 전 또는 4시간 후에 복용하십시오.', '레보티록신과 최소 4시간 띄워 드세요', '갑상선약(레보티록신)과 철분제를 몇 시간 띄워 먹어야 하나요?', 'N1', 'Levothyroxine (MedlinePlus)', 'https://medlineplus.gov/druginfo/meds/a682461.html', 'other', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('doxycycline-iron', 'substance', 'doxycycline', 'substance', 'iron', 'separate_timing', NULL, 'If you are taking iron preparations and vitamin products that contain iron, take them 3 hours before or 2 hours after doxycyline.', '철분 제제나 철분이 든 비타민 제품을 복용한다면, 독시사이클린 복용 3시간 전 또는 2시간 후에 복용하십시오.', '철분제는 독시사이클린 복용 3시간 전 또는 2시간 후에 먹는다.', '독시사이클린(항생제)과 철분제를 몇 시간 띄워 먹어야 하나요?', 'N2', 'Doxycycline (MedlinePlus)', 'https://medlineplus.gov/druginfo/meds/a682063.html', 'other', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('doxycycline-calcium', 'substance', 'doxycycline', 'substance', 'calcium', 'separate_timing', NULL, 'if you are taking antacids, calcium supplements, and laxatives containing magnesium, take them 1-2 before or after doxycyline.', '제산제, 칼슘 보충제, 마그네슘이 든 완하제(변비약)를 복용한다면, 독시사이클린 복용 1-2(원문에 시간 단위 없음) 전 또는 후에 복용하십시오.', '칼슘제는 독시사이클린과 복용 시간을 띄운다. 원문은 ''1-2 before or after''로 시간 단위가 빠져 있으므로 간격은 약사에게 확인한다.', '독시사이클린(항생제)과 칼슘제를 몇 시간 띄워 먹어야 하나요?', 'N2', 'Doxycycline (MedlinePlus)', 'https://medlineplus.gov/druginfo/meds/a682063.html', 'other', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('ciprofloxacin-calcium', 'substance', 'ciprofloxacin', 'substance', 'calcium', 'separate_timing', NULL, 'you should know that if you are taking antacids or multivitamins containing calcium, magnesium hydroxide, aluminum hydroxide, zinc or iron; or certain medications such as didanosine solution; phosphate binders such as sevelamer or lanthanum carbonate; or sucralfate, take them at least 6 hours before or 2 hours after ciprofloxacin.', '칼슘, 수산화마그네슘, 수산화알루미늄, 아연 또는 철분이 든 제산제나 종합비타민, 디다노신 액제 같은 일부 약, 세벨라머·탄산란타넘 같은 인산염 결합제, 수크랄페이트를 복용한다면, 시프로플록사신 복용 최소 6시간 전 또는 2시간 후에 복용하십시오.', '칼슘이 든 제품은 시프로플록사신 복용 최소 6시간 전 또는 2시간 후에 먹는다.', '시프로플록사신(항생제)과 칼슘제를 몇 시간 띄워 먹어야 하나요?', 'N3', 'Ciprofloxacin (MedlinePlus)', 'https://medlineplus.gov/druginfo/meds/a688016.html', 'other', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('ciprofloxacin-zinc', 'substance', 'ciprofloxacin', 'substance', 'zinc', 'separate_timing', NULL, 'you should know that if you are taking antacids or multivitamins containing calcium, magnesium hydroxide, aluminum hydroxide, zinc or iron; or certain medications such as didanosine solution; phosphate binders such as sevelamer or lanthanum carbonate; or sucralfate, take them at least 6 hours before or 2 hours after ciprofloxacin.', '칼슘, 수산화마그네슘, 수산화알루미늄, 아연 또는 철분이 든 제산제나 종합비타민, 디다노신 액제 같은 일부 약, 세벨라머·탄산란타넘 같은 인산염 결합제, 수크랄페이트를 복용한다면, 시프로플록사신 복용 최소 6시간 전 또는 2시간 후에 복용하십시오.', '아연이 든 제품은 시프로플록사신 복용 최소 6시간 전 또는 2시간 후에 먹는다.', '시프로플록사신(항생제)과 아연제를 몇 시간 띄워 먹어야 하나요?', 'N3', 'Ciprofloxacin (MedlinePlus)', 'https://medlineplus.gov/druginfo/meds/a688016.html', 'other', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('ciprofloxacin-iron', 'substance', 'ciprofloxacin', 'substance', 'iron', 'separate_timing', NULL, 'you should know that if you are taking antacids or multivitamins containing calcium, magnesium hydroxide, aluminum hydroxide, zinc or iron; or certain medications such as didanosine solution; phosphate binders such as sevelamer or lanthanum carbonate; or sucralfate, take them at least 6 hours before or 2 hours after ciprofloxacin.', '칼슘, 수산화마그네슘, 수산화알루미늄, 아연 또는 철분이 든 제산제나 종합비타민, 디다노신 액제 같은 일부 약, 세벨라머·탄산란타넘 같은 인산염 결합제, 수크랄페이트를 복용한다면, 시프로플록사신 복용 최소 6시간 전 또는 2시간 후에 복용하십시오.', '철분이 든 제품은 시프로플록사신 복용 최소 6시간 전 또는 2시간 후에 먹는다.', '시프로플록사신(항생제)과 철분제를 몇 시간 띄워 먹어야 하나요?', 'N3', 'Ciprofloxacin (MedlinePlus)', 'https://medlineplus.gov/druginfo/meds/a688016.html', 'other', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('levofloxacin-iron', 'substance', 'levofloxacin', 'substance', 'iron', 'separate_timing', NULL, 'you should know if you are taking antacids, vitamins, or mineral supplements containing aluminum hydroxide, magnesium hydroxide, iron or zinc, or certain medications such as didanosine solution or sucralfate, take them at least 2 hours before or after levofloxacin.', '수산화알루미늄, 수산화마그네슘, 철분 또는 아연이 든 제산제·비타민·미네랄 보충제나 디다노신 액제·수크랄페이트 같은 일부 약을 복용한다면, 레보플록사신 복용 최소 2시간 전 또는 후에 복용하십시오.', '철분이 든 제품은 레보플록사신 복용 최소 2시간 전 또는 후에 먹는다.', '레보플록사신(항생제)과 철분제를 몇 시간 띄워 먹어야 하나요?', 'N4', 'Levofloxacin (MedlinePlus)', 'https://medlineplus.gov/druginfo/meds/a697040.html', 'other', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('levofloxacin-zinc', 'substance', 'levofloxacin', 'substance', 'zinc', 'separate_timing', NULL, 'you should know if you are taking antacids, vitamins, or mineral supplements containing aluminum hydroxide, magnesium hydroxide, iron or zinc, or certain medications such as didanosine solution or sucralfate, take them at least 2 hours before or after levofloxacin.', '수산화알루미늄, 수산화마그네슘, 철분 또는 아연이 든 제산제·비타민·미네랄 보충제나 디다노신 액제·수크랄페이트 같은 일부 약을 복용한다면, 레보플록사신 복용 최소 2시간 전 또는 후에 복용하십시오.', '아연이 든 제품은 레보플록사신 복용 최소 2시간 전 또는 후에 먹는다.', '레보플록사신(항생제)과 아연제를 몇 시간 띄워 먹어야 하나요?', 'N4', 'Levofloxacin (MedlinePlus)', 'https://medlineplus.gov/druginfo/meds/a697040.html', 'other', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;
INSERT INTO interaction_rule (id, a_type, a_ref, b_type, b_ref, relation, effect, quote, quote_ko, action, pharmacist_question, source_id, source_title, source_url, source_kind, source_note, more_sources, checked_on) VALUES ('alendronate-calcium', 'substance', 'alendronate', 'substance', 'calcium', 'separate_timing', NULL, 'the following nonprescription or herbal products may interact with alendronate: aspirin and other nonsteroidal anti-inflammatory drugs (NSAIDs such as ibuprofen or naproxen), mineral oils, calcium supplements, or antacids (e.g. - calcium carbonate, milk of magnesia, famotidine, ranitidine, omperazole, esomeprazole, lansoprazole). if you are taking any other medications including supplements, vitamins, or antacids by mouth, take them at least 30 minutes after you take alendronate.', '다음 일반의약품이나 생약 제품은 알렌드론산과 상호작용할 수 있습니다: 아스피린과 그 밖의 비스테로이드소염진통제(이부프로펜, 나프록센 등), 미네랄 오일, 칼슘 보충제, 제산제(예: 탄산칼슘, 수산화마그네슘 현탁액, 파모티딘, 라니티딘, 오메프라졸, 에스오메프라졸, 란소프라졸). 보충제·비타민·제산제를 포함해 다른 약을 입으로 복용한다면, 알렌드론산을 복용하고 최소 30분이 지난 뒤에 복용하십시오.', '칼슘제는 알렌드론산을 복용하고 최소 30분이 지난 뒤에 먹는다.', '골다공증약(알렌드론산)과 칼슘제는 얼마나 띄워 먹어야 하나요?', 'N5', 'Alendronate (MedlinePlus)', 'https://medlineplus.gov/druginfo/meds/a601011.html', 'other', NULL, '[]'::jsonb, '2026-10-29') ON CONFLICT (id) DO NOTHING;

COMMIT;

